window.NOTES = {"groups":[{"id":"start","title":"시작하기","day":""},{"id":"basic","title":"기본기","day":"DAY 1"},{"id":"pattern1","title":"패턴 ①","day":"DAY 1"},{"id":"pattern2","title":"패턴 ②","day":"DAY 2"},{"id":"framework","title":"프레임워크","day":"DAY 2"},{"id":"advanced","title":"고급 기술","day":"DAY 3"},{"id":"tools","title":"도구와 정리","day":""}],"topics":[{"id":"why","group":"start","title":"프롬프트가 뭐고, 왜 배울까","en":"What is a Prompt","summary":"AI는 내가 말한 만큼만 안다. 빠진 정보는 AI가 마음대로 채운다.","points":["프롬프트는 ChatGPT·Gemini·Claude 같은 AI에게 평소 말로 주는 명령이다.","AI의 답은 정답이 아니라 '가장 그럴듯한 답(확률)'이다. 두루뭉술하게 물으면 뻔한 답, 구체적으로 물으면 원하는 범위 안의 답이 나온다.","AI는 '지능이 높은 초등학생'과 같다. 설명을 잘 해 주면 잘하고, 대충 말하면 엉뚱하게 한다.","식당 주문과 같다. '아무거나 주세요'보다 '김치찌개 2인분, 덜 맵게, 12시까지 포장'이 원하는 결과를 준다.","바이브 코딩에서는 명령할 때마다 토큰(=돈)이 든다. 목표는 10번 물을 걸 5번으로 줄이는 것."],"blocks":[{"type":"table","head":["대충 쓴 프롬프트","필요한 정보가 다 있는 프롬프트"],"rows":[["\"메일 써 줘\"","\"베트남 바이어에게, 샘플 발송을 알리는, 정중한 영어 메일, 5줄\""],["\"구구단 만들어 줘\" → 5~6번 다시 시킴","\"초등학생용 구구단 웹페이지, 단 선택 버튼 2~9, 문제 10개, 정답이면 초록색, 모바일도 크게, HTML 한 파일로\" → 1~2번이면 끝"]]}],"fixes":[["답이 두루뭉술하다","types"],["형식이 매번 제각각이다","shots"],["수준·관점이 안 맞는다","persona"],["요청이 길어지면 놓친다","markdown"],["중요한 조건을 무시한다","strength"],["답이 하나뿐이다","alternatives"],["순서 없이 늘어놓는다","recipe"],["그럴듯하게 틀린다","verifier"],["주고받으며 진행해야 한다","game"],["내 질문 자체가 애매하다","refine"],["긴 명령을 매번 반복한다","meta"],["첫 답이 대충이다","reflection"],["일반론만 늘어놓는다","context"],["매번 구성이 막막하다","frameworks"]]},{"id":"types","group":"basic","title":"세 가지 유형","en":"Narrative · Instruction · Function","summary":"맥락을 말할까(서술형), 규칙을 줄까(지침형), 틀을 줄까(함수형).","points":["서술형: 역할·배경·목적을 이야기하듯 설명한다. 자유롭지만 쓸 때마다 상황을 다시 설명해야 한다.","지침형: 꼭 지킬 것을 1, 2, 3 규칙으로 나열한다.","함수형: 입력 → 처리 → 출력 틀을 정해 두고 { } 안의 값만 바꿔 재사용한다. 엑셀 수식에 숫자만 바꿔 넣는 것과 비슷하다.","섞어 써도 된다. 설명은 서술형, 꼭 지킬 것은 지침형, 결과 모양은 함수형으로."],"blocks":[{"type":"table","head":["유형","핵심","재사용","유연성","이럴 때"],"rows":[["서술형","맥락","낮음","높음","처음 상황을 설명할 때"],["지침형","규칙","중간","중간","꼭 지킬 조건이 있을 때"],["함수형","구조","높음","낮음","같은 작업을 반복할 때"]]}],"prompts":[{"id":"d1s12_0","lab":"실습 · 서술형","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"당신은 10년 경력의 무역 전문가입니다.\n중소기업 수출 담당자가 HS code를 처음 배우는 상황입니다.\n이 사람에게 HS code의 개념과 중요성을 설명해 주세요.","kind":"try"},{"id":"d1s13_0","lab":"수업정리본 예시 (코드 작성 규칙)","where":"참고용 (읽어 보기)","text":"1. 함수명은 snake_case로 작성\n2. 각 함수의 docstring 포함\n3. 예외 처리 반드시 포함\n4. 결과는 json 형식으로 반환","kind":"ref"},{"id":"d1s13_1","lab":"실습 · 지침형 (무역 버전)","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 규칙을 지켜서 바이어에게 보낼 납기 지연 안내 메일을 작성해 주세요.\n1. 첫 문장에 사과를 넣을 것\n2. 지연 이유는 한 문장으로\n3. 새 납기일을 굵게 표시\n4. 영어로 작성하고 5문장 이내로","kind":"try"},{"id":"d1s14_0","lab":"실습 · 함수형","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"입력 : {product_name} , {hs_code} , {country}\n처리 : 해당 국가의 관세율 및 수입 규제 조회\n출력 : {\n  \"관세율\" : \"\",\n  \"규제사항\" : [],\n  \"필요서류\" : []\n}","kind":"try"},{"id":"d1s16_0","lab":"서술형","where":"Gemini 새 채팅 ①","text":"당신은 나를 위로하는 전용 챗봇 '소담'이야. 나는 업무가 힘든 직장인이고 이번 주 야근을 해야 해. 위로와 함께 기운 낼 수 있는 메시지를 공손한 존댓말로, 유머러스하고 상냥하게 써줘. 나를 '주인님'이라고 부르고 500자 이상으로.","kind":"try"},{"id":"d1s16_1","lab":"지침형","where":"Gemini 새 채팅 ②","text":"당신은 위로 챗봇 '소담'입니다.\n다음을 반영해 메시지를 쓰세요.\n1. 상황: 업무가 힘든 직장인, 이번 주 야근\n2. 내용: 위로 + 힘이 되는 말\n3. 말투: 공손, 유머러스, 상냥\n4. 호칭: 주인님\n5. 분량: 500자 이상","kind":"try"},{"id":"d1s16_2","lab":"함수형","where":"Gemini 새 채팅 ③ → 셋 비교","text":"입력 : {주제} = 야근하는 직장인 위로\n       {독자} = 나\n       {말투} = 공손 · 유머 · 상냥\n처리 : 위로 메시지 작성\n출력 : {\n  \"호칭\" : \"주인님\",\n  \"메시지\" : \"(500자 이상)\"\n}","kind":"try"},{"id":"d1s17_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"입력 : {만들 것} = 환율 계산기 웹페이지\n       {사용자} = 무역을 처음 배우는 신입\n       {기능} = 원화 금액 입력 → 달러·동(VND) 변환\n처리 : HTML · CSS · JavaScript를 한 파일로 작성\n출력 : index.html 전체 코드 + 쉬운 사용 설명 3줄","kind":"vibe"}],"work":["서술형: 처음 하는 일, 아이디어 상담","지침형: 견적 메일 규칙, 보고서 양식처럼 매번 지킬 규칙이 있는 일","함수형: 제품 50개 설명, 국가별 안내문처럼 값만 바꿔 반복하는 일"]},{"id":"shots","group":"basic","title":"예시 주기 (제로·원·퓨샷)","en":"Zero · One · Few-shot","summary":"예시를 주면 AI가 그 틀 안에서만 답을 찾는다.","points":["샷 = 예시의 개수. 제로샷(0개)은 AI가 마음대로 넓게 답한다.","원샷(1개)은 '이런 모양으로 답해'를 보여 준다. 긴 설명 없이 예시와 같은 모양으로 답이 나온다.","퓨샷(2개 이상)은 선택지와 애매한 경우의 기준까지 알려 준다. 대표 예시 몇 개면 충분하다."],"prompts":[{"id":"d1s20_0","lab":"실습 · 제로샷","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"이 제품 정말 맘에 들어","kind":"try"},{"id":"d1s20_1","lab":"하나 더","where":"같은 방법으로 새 채팅에","text":"강아지에 대해서 설명해주세요","kind":"try"},{"id":"d1s21_0","lab":"실습 · 원샷","where":"Gemini 새 채팅 (샷마다 새 채팅)","text":"감정을 분류해 주세요\n예시)\n\"배송이 너무 늦어서 실망했어요\"\n감정 : 부정\n\n이 제품 정말 맘에 들어요\n감정 :","kind":"try"},{"id":"d1s22_0","lab":"실습 · 퓨샷","where":"Gemini 새 채팅 (샷마다 새 채팅)","text":"감정을 분류해 주세요 (긍정/부정/중립)\n예시)\n텍스트 : \"배송이 너무 늦어서 실망이야\" -> 부정\n텍스트 : \"그냥 평범한 제품이야\" -> 중립\n텍스트 : \"역대급 만족이야\" -> 긍정\n텍스트 : \"품질은 좋은데 가격이 비싸요\" -> 중립\n\n텍스트 : \"이 제품 정말 맘에 들어\"\n감정 :","kind":"try"},{"id":"d1s23_0","lab":"실습 · 퓨샷 (HS Code)","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"HS Code를 분류해 주세요\n예시)\n품목 : \"면으로 만든 남성용 티셔츠\" -> 6109.10\n품목 : \"폴리에스테르 소재 여성 블라우스\" -> 6206.40\n품목 : \"아동용 데님 바지\" -> 6203.42\n\n품목 : \"울 혼방 남성 재킷\"\nHS Code :","kind":"try"},{"id":"d1s24_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"아래 예시와 똑같은 형식으로 수출 품목 샘플 데이터를 JSON으로 10개 더 만들어 주세요\n예시)\n{\"품목\": \"면 티셔츠\", \"HS\": \"6109.10\", \"수출국\": \"베트남\", \"단가_USD\": 3.2}\n{\"품목\": \"스테인리스 냄비\", \"HS\": \"7323.93\", \"수출국\": \"태국\", \"단가_USD\": 8.5}","kind":"vibe"}],"work":["바이어 메일 제목 형식 통일: 예시 2~3개 주고 '이 형식으로'","HS Code·품목 분류를 같은 자릿수로 받기","회사 제품 설명을 기존 톤 그대로 새 제품에 적용"],"caution":"AI가 준 HS Code는 참고용이다. 실제 업무에서는 관세청 등 공식 자료로 꼭 확인한다."},{"id":"persona","group":"basic","title":"페르소나 (역할 주기)","en":"Persona","summary":"역할을 주면 AI가 그 사람의 말투와 지식, 집중하는 부분까지 가져온다.","points":["같은 '계약서 검토해 줘'도 변호사는 법적 위험, CFO는 재무 조건, 신입사원은 쉬운 설명에 집중한다.","좋은 페르소나 4요소: 역할 + 경력/배경 + 전문 분야 + 말투/태도.","약한 페르소나('전문가처럼')보다 강한 페르소나('20년 경력 관세사, FTA 원산지 전문, 실무자에게 쉽게')가 답의 범위를 좁혀 준다.","멀티 페르소나: 성격이 다른 여러 전문가에게 동시에 물어 회의하듯 의견을 받는다."],"blocks":[{"type":"table","head":["페르소나","AI가 집중하는 것"],"rows":[["없음","일반적인 설명"],["변호사","법적 리스크"],["CFO (재무 책임자)","재무 조건, 수익성"],["신입사원","쉽고 친절한 설명"]]}],"prompts":[{"id":"d1s27_0","lab":"실습 · 관세사 페르소나","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"당신은 20년 경력의 관세사입니다.\nFTA 협정세율과 원산지 규정의 전문가로\n중소기업 무역 담당자에게 복잡한 내용을\n쉽고, 실용적으로 설명하는 것이 특기입니다.\n\n질문: FTA를 활용하면 관세가 어떻게 줄어드나요?","kind":"try"},{"id":"d1s28_0","lab":"비평가 페르소나","where":"Gemini 새 채팅 → 끝에 내 질문 한 줄 추가","text":"당신은 까다로운 개발자입니다.\n코드 리뷰 시 성능, 보안, 가독성을 엄격하게 평가하며\n칭찬보다 개선점을 먼저 지적하는 스타일입니다.","kind":"try"},{"id":"d1s28_1","lab":"동기부여 코치 페르소나","where":"Gemini 새 채팅 → 끝에 내 질문 한 줄 추가","text":"당신은 \"세계 최고의 동기부여 코치\"입니다. 당신은 매우 통찰력 있고 영감을 주는 방식으로, 창의적이고 임팩트 있는 조언을 제공합니다. 상대방의 목표와 도전을 깊이 이해하고, 능력을 최대한 발휘할 수 있도록 도와줍니다. 어떤 상황에서도 긍정적이고 효과적인 해결책을 자세하게 제시합니다.","kind":"try"},{"id":"d1s30_0","lab":"실습 · 멀티 페르소나","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"다음 3명의 전문가 입장에서 우리 제품의 동남아 수출 전략을 분석해 주세요\n- 김부장(영업 15년, 낙관적, 현장 중심)\n- 이박사(시장조사 전문, 데이터 중심, 신중함)\n- 박대표(스타트업 창업가, 속도 중시, 리스크 감수)\n각자의 관점에서 찬반 의견을 제시하세요","kind":"try"},{"id":"d1s31_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"당신은 비전공자에게 설명하는 것이 특기인 친절한 시니어 웹 개발자입니다.\n아래 기능을 가진 \"바이어 연락처 메모장\" 웹페이지를 만들어 주세요.\n- 이름, 국가, 메모 입력 후 저장 버튼\n- 저장한 목록이 아래에 표로 보이기\n코드를 준 뒤, 각 부분이 무슨 일을 하는지 초등학생도 알게 설명해 주세요.","kind":"vibe"}],"work":["바이어 문의 답장: '10년 차 무역 실무자'로 → 실무 용어·순서가 정확해짐","계약서 검토: '국제 계약 전문 변호사 시각에서 위험 조항 찾기'","멀티 페르소나: 영업·재무·물류 관점으로 동시에 검토 → 회의 준비"]},{"id":"markdown","group":"basic","title":"마크다운으로 정리하기","en":"Markdown","summary":"#, -, > 같은 기호로 역할·조건·출력을 나눠 주면 AI가 헷갈리지 않는다.","points":["AI는 글을 잘게 쪼개서(파싱) 이해한다. 기호로 구분해 주면 더 정확하고 일관된 답이 나온다.","좋은 프롬프트의 뼈대 5칸: #역할 · #작업 · #입력 · #제약 · #출력. 이 순서로만 채워도 한두 번에 원하는 답에 가까워진다.","''' 로 감싸면 '이건 내가 준 자료'라는 표시가 된다. 코드가 아니어도 계약서 문장, 이메일 원문 등에 쓴다."],"blocks":[{"type":"table","head":["기호","이름","쓰임"],"rows":[["#","헤더(제목)","프롬프트의 뼈대. # 큰 제목, ## 중간, ### 소제목"],["'''","코드 블록","내가 넣는 자료를 지시문과 따로 묶기"],[">","인용문","절대 지켜야 할 조건 강조"],["-","목록","조건·제약을 나열"],["|","표","입력·출력 예시를 표로 (₩ 키 + Shift)"],["**글자**","굵게 / *기울임*","변수나 중요한 단어 강조"]]}],"prompts":[{"id":"d1s35_0","lab":"# 헤더: 할 일을 제목처럼","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"#역할\n당신은 10년 경력의 관세사입니다\n#작업\nHS CODE를 분류하세요\n#출력 형식\njson으로 반환","kind":"try"},{"id":"d1s35_1","lab":"''' 코드 블록: 자료를 따로 묶기","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"아래 python 코드의 버그를 찾아주세요\n'''\npython\ndef calculate_tax(price) :\nreturn price*0.1\nprint(\"완료\") #버그위치\n'''","kind":"try"},{"id":"d1s36_0","lab":"> 인용문: 꼭 지킬 조건","where":"Gemini 새 채팅 (Claude에서도 비교)","text":">반드시 한국어로만 답변하세요\n>추측성 내용은 포함하지 마세요","kind":"try"},{"id":"d1s36_1","lab":"- 목록: 조건 나열","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"##제약조건\n- 답변은 500자 이내\n- 전문 용어 사용 시 괄호 안에 설명 추가\n- 불확실한 내용은 \"확인 필요\"로 표시\n- 예시는 반드시 무역 도메인에서 선택","kind":"try"},{"id":"d1s37_0","lab":"| 표: 이런 모양으로 답해 줘","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"##예시\n| 입력 품목 | HS Code | 관세율 |\n| 면 티셔츠 | 6109.10 | 13% |\n| 블라우스 | 6206.40 | 14% |\n| 데님바지 | 6203.42 | 15% |\n\n위 형식으로 \"울 남성 재킷\", \"가죽 장갑\"을 정리해줘","kind":"try"},{"id":"d1s37_1","lab":"**굵게** · *기울임*","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"**[분석대상]**에 대해 *반드시* 아래 순서대로 분석하세요","kind":"try"},{"id":"d1s39_0","lab":"실습 · 마크다운 통합","where":"Gemini 새 채팅 → JSON 결과 확인 (Claude에서도 비교)","text":"#역할\n당신은 중소기업 수출 컨설턴트입니다\nFTA 활용과 원산지 증명 전문가입니다\n#작업\n아래 수출 품목에 대한 FTA 적용 가능 여부를 분석하세요\n'''\n품목명 : 스테인리스 주방용품\n수출국 : 한국\n수입국 : 베트남\n'''\n#분석 기준\n- 한-아세안 FTA 협정 세율 적용 여부\n- 원산지 결정 기준 충족 여부\n- 필요 서류 목록\n#제약 조건\n>확실하지 않은 세율은 반드시 \"세관 확인 필요\"로 표기\n#출력 형식\n'''JSON\n{\"FTA_적용\": TRUE/FALSE, \"협정세율\": \"\",\n \"일반세율\": \"\", \"필요서류\": []}\n'''","kind":"try"},{"id":"d1s40_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"#만들 것\n무역 용어 퀴즈 웹페이지\n#기능\n- 문제 10개 (FOB, CIF, HS Code 등)\n- 4지선다, 고르면 바로 정답/오답 표시\n- 마지막에 점수 보여 주기\n#디자인\n- 흰 배경, 파란 버튼, 모바일에서도 보기 좋게\n#제약 조건\n> HTML, CSS, JavaScript 한 파일로\n#출력\nindex.html 전체 코드","kind":"vibe"}],"work":["업무 지시서·보고서 요청을 #목적 #자료 #조건 #형식 틀로 → 빠뜨리는 항목이 없음","팀에서 같은 틀을 공유하면 누가 써도 비슷한 품질","긴 자료(계약 조건, 제품 스펙)는 ''' 로 따로 묶기"],"caution":"표 예시의 관세율 숫자는 연습용 가상 값이다."},{"id":"strength","group":"basic","title":"강도 · 톤","en":"Strength & Tone","summary":"'참고하세요'와 '반드시'의 차이를 AI는 민감하게 알아듣는다.","points":["강도 4단계: ① 권장(가능하면) → ② 일반(~하세요) → ③ 강조(반드시, 꼭) → ④ 절대(절대로, 예외 없이).","우선순위를 신호등 이모지로 표시하면 AI도 무엇이 가장 중요한지 구분한다. (🔴 절대 · 🟡 중요 · ✅ 선택)","네거티브 프롬프트: '~하지 마세요'로 뺄 것을 미리 알려 준다.","숫자로 말하기: '짧게' → '3문장으로', '몇 가지' → '정확히 3가지'. 기준도 정해 준다: '무역영어 1급 수준으로'.","톤 = 말투. 페르소나를 주면 톤도 따라온다."],"blocks":[{"type":"table","head":["약하게","→","강하게"],"rows":[["참고하세요","활용하세요","반드시 포함하세요 / 절대 빠뜨리지 마세요"],["검토하세요","분석하세요","철저히 검증하세요"],["말해주세요","설명하세요","단계별로 명확히 서술하세요"]]}],"prompts":[{"id":"d1s44_0","lab":"마크다운 + 이모지 우선순위","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"## 우선순위\n🔴최우선(절대조건)\n- 개인 정보 절대 출력하지 않는다\n- 사실과 다른 내용을 생성하지 않는다\n🟡중요(일반 조건)\n- 답변은 500자 이내로 작성\n- 전문 용어 괄호 설명 추가\n✅선택(권장 조건)\n- 가능하면 실제 사례를 포함\n- 표나 목록을 활용하면 더 좋다","kind":"try"},{"id":"d1s46_0","lab":"실습 · 톤 바꾸기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"#입력\n[원본] 올해 들어 회사는 큰 변화를 맞이했습니다. 이제 새로운 전략과 목표를 설정하고, 모든 직원이 함께 나아가려고 합니다.\n\n#처리\n다음 각각의 톤에 맞춰 [원본] 글을 수정해 주세요\n1. 유머러스한\n2. 감정적인\n3. 따뜻한\n4. 아이러니한\n5. 로맨틱한","kind":"try"},{"id":"d1s47_0","lab":"실습 · 내 메시지 톤 고르기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"#입력\n[원본] 선배님 안녕하세요. 저는 무역 쪽 취업을 준비하고 있는데요, 혹시 시간 괜찮으시면 커피 한잔하면서 이야기 들을 수 있을까요?\n\n#처리\n위 메시지를 아래 톤으로 각각 다듬어 주세요\n1. 정중하고 공손한\n2. 밝고 친근한\n3. 짧고 깔끔한 비즈니스\n4. 진심이 느껴지는","kind":"try"},{"id":"d1s48_0","lab":"바이브 코딩에서","where":"앞 실습(퀴즈)을 한 Claude 채팅에 이어서 입력","text":"방금 만든 퀴즈 페이지를 아래처럼 수정해 주세요.\n[반드시] 기존 문제와 점수 기능은 절대 바꾸지 마세요.\n[변경] 버튼 높이 48px, 글자 크기 18px, 버튼 사이 간격 12px\n[변경] 정답이면 초록색, 오답이면 빨간색으로 표시\n[출력] 수정된 전체 코드","kind":"vibe"}],"work":["'단가는 절대 메일 본문에 쓰지 마' 같은 보안 규칙","'3줄 이내', '영문 120단어' → 길이가 정확해짐","처음 바이어엔 정중하게, 오래 거래한 바이어엔 친근하게"],"caution":"AI의 환각(지어낸 답)을 완전히 없앨 수는 없다. 중요한 사실은 사람이 최종 확인한다."},{"id":"alternatives","group":"pattern1","title":"대안 접근법","en":"Alternative Approaches","summary":"AI에게 결정을 맡기지 말고, 여러 대안을 받아 내가 고른다.","points":["단순 나열형: 방법을 최소 몇 가지, 정해진 형식으로 받는다.","축(기준) 비교형: 속도·비용 같은 기준마다 선택지를 정해 주고 비교표로 받는다.","상황별 분기형: 상황 A, B, C마다 다른 추천을 받는다.","역발상형: '하지 않는' 선택지, '문제 자체를 다시 정의'하는 방법까지 받는다."],"prompts":[{"id":"d1s51_0","lab":"실습 · 나열형","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"#지시\n아래 문제를 해결하는 방법을 최소 4가지 제시하세요\n각 방법은 아래 형식으로 작성하세요\n## 방법 {번호}:{이름}\n- 핵심 원리 : {한줄}\n- 적합한 상황 : {언제 쓰면 좋은가}\n- 단점 : {주의 할 점}\n- 난이도 : {초급/중급/고급}\n#문제\n수출 통관 서류를 자동으로 생성하고 싶습니다","kind":"try"},{"id":"d1s52_0","lab":"수업정리본 예시","where":"참고용 (읽어 보기)","text":"아래 4가지 방법을 다음 기준으로 비교 분석하세요\n평가기준 :\n- 개발 속도 (빠름/보통/느림)\n- 유지 보수 난이도 (쉬움/보통/어려움)\n- 비용 : (무료/저비용/고비용)\n- 확장성 : (높음/보통/낮음)\n비교대상 : FastAPI, Django, Flask, Node.js Express\n용도 : 무역 데이터 처리 REST API 서버","kind":"ref"},{"id":"d1s52_1","lab":"실습 · 쉬운 버전 (운송 수단)","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 4가지 운송 방법을 다음 기준으로 비교하고 표로 정리하세요\n평가기준 :\n- 속도 (빠름/보통/느림)\n- 비용 (저비용/보통/고비용)\n- 대량 화물 (적합/보통/부적합)\n비교대상 : 해상 운송, 항공 운송, 철도 운송, 트럭 운송\n용도 : 한국에서 유럽으로 화장품 수출","kind":"try"},{"id":"d1s53_0","lab":"실습 · 상황별 추천","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 상황별 가장 적합한 데이터베이스를 추천하세요\n각 상황은 독립적으로 판단하세요\n상황 A : 스타트업, 개발자 1명, 빠른 MVP\n상황 B : 무역데이터 10년치, 복잡한 통계 쿼리\n상황 C : 실시간 환율·가격 데이터, 초당 1000건 업데이트\n상황 D : 문서 형태의 비정형 통관 데이터 저장\n\n각 상황에 대해 :\n1순위 추천 : {DB명} - {이유 한줄 설명}\n2순위 추천 : {DB명} - {이유 한줄 설명}","kind":"try"},{"id":"d1s54_0","lab":"실습 · 역발상","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 문제에 대해 일반적인 해결책뿐 아니라\n\"하지 않는\" 선택지와 \"문제 자체를 재정의\"하는 방법도 대안으로 포함하여 총 5가지를 제시하세요\n문제 : 수입 통관 처리 시간이 너무 오래 걸린다","kind":"try"},{"id":"d1s58_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"무역 용어 퀴즈 앱에 점수 기록 저장 기능을 넣고 싶어요.\n바로 만들지 말고, 구현 방법 3가지를\n[난이도, 비용, 장점, 단점]으로 비교표로 보여 주세요.\n이 답을 듣는 사람은 코딩을 처음 배우는 비전공 대학생입니다.\n마지막에 저에게 가장 맞는 방법 하나를 추천해 주세요.","kind":"vibe"}],"work":["운송 방법·결제 조건을 장단점 비교표로 받아서 내가 결정"],"caution":"바이브 코딩에서는 '바로 만들지 말고 방법부터 비교'가 중요하다. 처음 방법을 잘못 고르면 다 다시 만들어야 한다."},{"id":"userpersona","group":"pattern1","title":"이용자 페르소나","en":"User Persona","summary":"말하는 사람(AI)이 아니라 '듣는 사람'을 정해 주면 설명 수준과 말투가 맞춰진다.","points":["페르소나 패턴은 AI의 역할을, 이용자 페르소나는 답을 듣는 사람을 정한다.","듣는 사람 정보를 구체적으로: 직책, 경험, 관심사, 걱정, 읽을 시간.","체크리스트: 직업과 역할은? 사전 지식은? 이 정보로 무엇을 결정하나? 급한가? 얼마나 긴 답을 읽을 수 있나? 가장 두려워하는 것과 원하는 것은? 쓰면 안 되는 표현은?"],"prompts":[{"id":"d1s55_0","lab":"실습 · 듣는 사람 바꾸기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"질문 : \"블록체인\"이 무역 업무에 어떻게 활용되나요?\n아래 세 이용자에게 각각 맞춰서 설명해 주세요\n이용자 1 : 무역을 처음 배우는 대학생\n이용자 2 : 중소기업 수출 담당 팀장\n이용자 3 : 금융 기관 IT 의사결정자","kind":"try"},{"id":"d1s56_0","lab":"실습 · 이용자 정보","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"#이용자 정보\n- 직책 : 중소기업 대표 (제조업, 직원 30명)\n- 수출 경험 : 국내 영업만 10년, 해외 수출 처음\n- 관심사 : 리스크 최소화, 빠른 실행\n- 우려 사항 : \"복잡하고 어려울 것 같다\"는 막연한 두려움\n- 시간 : 바빠서 긴 글을 읽지 않음\n#지시\n위의 이용자에게 첫 수출 준비 3단계를 설명하세요\n전문 용어는 최소화하고 각 단계는 3줄 이내로 작성하세요","kind":"try"}],"work":["같은 보고를 팀장용(요약)·신입용(쉽게)·바이어용(영문)으로","'이 답을 듣는 사람은 ~'으로 설명 수준 맞추기"]},{"id":"recipe","group":"pattern1","title":"레시피 패턴","en":"Recipe","summary":"'다음에 뭘 하지?'를 줄여 주는 순서 있는 행동 지침 받기.","points":["목표 + 현재 상태를 알려 주면 내 수준에 맞는 단계가 나온다.","각 단계에 '완료 기준'을 넣으면 다음 단계로 넘어갈 때를 알 수 있다.","분기형(정상/이상 대응), 체크리스트형([ ] 행동 - 이유), 병렬형(날짜별로 동시에 할 일)으로 바꿔 쓸 수 있다."],"prompts":[{"id":"d1s61_0","lab":"실습 · 기본 레시피","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"#목표\nPython 초보자가 무역 HS code 자동 분류 프로그램 만들기\n#현재 상태\n- Python 설치만 되어 있음\n- 프로그램 경험 없음\n- 엑셀로 품목 데이터 500개 보유\n#요청\n위의 목표를 달성하기 위한 단계별 레시피를 작성하세요\n각 단계는 아래 형식으로 작성하세요\n##STEP{번호} : {단계명}\n- 할일 : {구체적 행동}\n- 소요 시간 : {예상 기간}\n- 완료 기준 : {이것이 되면 다음으로}\n- 주의 사항 : {흔한 실수}","kind":"try"},{"id":"d1s62_0","lab":"실습 · 분기 레시피","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"무역 계약 클레임 처리 절차를 단계별로 작성하세요\n단, 각 단계에서 발생할 수 있는 분기 상황도 포함하세요\n형식 :\nstep N.{행동}\n  -정상 : {이 결과면 다음 단계로}\n  -이상 : {이 결과면 어떻게 대응}","kind":"try"},{"id":"d1s62_1","lab":"실습 · 체크리스트 레시피","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"신규 수출 거래처와의 첫 계약 체결을 위한 실행 체크리스트를 작성하세요\n형식 :\n[ ]{행동}-{이유 또는 주의사항}","kind":"try"},{"id":"d1s63_0","lab":"실습 · 병렬 레시피","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"첫 수출 준비 작업을 병렬 레시피로 만들어 주세요.\n1일차~10일차를 가로축으로 하고, 동시에 진행할 수 있는 작업은 같은 날짜에 겹쳐서 ■ 막대로 표시해 주세요.","kind":"try"}],"work":["첫 수출 절차를 단계별 체크리스트로","클레임처럼 혼자 대응하기 어려운 일은 단계와 예외 상황까지 받아 두기"]},{"id":"flipped","group":"pattern1","title":"뒤집힌 상호작용 (역질문)","en":"Flipped Interaction","summary":"내가 묻는 대신 AI가 나에게 질문하게 해서 빠진 정보를 채운다.","points":["나는 아는 만큼만 질문할 수 있다. AI가 내가 놓친 부분을 먼저 물어봐 준다.","일괄 질문: 필요한 정보를 한꺼번에 묻고, 나는 번호에 맞춰 한꺼번에 답한다.","하나씩 질문: 한 번에 하나만 묻고, 답하면 다음 질문으로 넘어간다.","AI가 질문했을 때는 새 채팅이 아니라 같은 채팅에 답한다."],"prompts":[{"id":"d1s64_0","lab":"방법 1 · 일괄 질문","where":"{목표}를 내 목표로 바꿔서 Gemini 새 채팅에","text":"제가 원하는 결과물은 {목표}입니다.\n바로 만들지 말고, 먼저 필요한 정보를 질문해 주세요\n모든 정보가 수집된 후 결과물을 작성하세요","kind":"try"},{"id":"d1s64_1","lab":"방법 2 · 하나씩","where":"{목표}를 내 목표로 바꿔서 Gemini 새 채팅에","text":"제가 원하는 결과물은 {목표}입니다\n한번에 하나의 질문만 하세요\n제가 답하면 다음 질문으로 넘어가고\n충분한 정보가 모이면 결과물을 작성하세요","kind":"try"},{"id":"d1s65_0","lab":"실습 · 일괄 질문","where":"Gemini 새 채팅 → AI가 질문하면 같은 채팅에 답하기","text":"수출 제안서를 작성해주세요\n바로 작성하지 말고, 먼저 아래 항목들을 질문해서\n제 답변을 모두 수집한 후 작성하세요\n수집이 필요한 정보 :\n- 타깃 바이어\n- 핵심 강점\n- 가격 정책\n- 납기 조건","kind":"try"},{"id":"d1s65_1","lab":"답변 예시","where":"이렇게 같은 채팅에 번호로 답하기","text":"1. 베트남의 중형 식품 유통업체\n2. 한국산 고품질, HACCP 인증\n3. 개당 2달러, 1,000개 이상 5% 할인\n4. 발주 후 30일 이내 선적","kind":"try"},{"id":"d1s66_0","lab":"실습 · 순차 질문","where":"Gemini 새 채팅 → 질문마다 같은 채팅에서 답하기","text":"저는 파이썬 학습 계획서를 만들고 싶어요.\n한 단계씩(step by step) 질문해 주세요.\n단, 한 번에 하나의 질문만 하고, 제 답변을 들은 뒤 다음 질문을 하세요.\n5~7개 질문이 끝나면 저에게 맞춘 학습 계획서를 작성해 주세요.","kind":"try"}],"work":["제안서·견적서 쓰기 전에 AI가 빠진 정보를 먼저 물어보게"]},{"id":"verifier","group":"pattern1","title":"인지 검증자","en":"Cognitive Verifier","summary":"어려운 질문은 작은 질문으로 쪼개서 하나씩 확인한 뒤 합친다.","points":["복잡한 질문을 한 번에 하면 AI가 스스로 실수를 못 찾고 그럴듯한 답(환각)을 만들 수 있다.","흐름: 복잡한 질문 → 하위 질문 3~5개 → 하나씩 답 → 통합된 답.","전문가 검증 방식: 확신이 없는 부분은 가정으로 표시하고 근거와 함께 단계적으로 결론을 낸다."],"prompts":[{"id":"d1s68_0","lab":"방법 1 · 명시적 분해 요청","where":"Gemini 새 채팅 (먼저 질문만 → 새 채팅에서 이 프롬프트로 비교)","text":"아래 질문에 바로 답하지 말고 먼저 이 질문을 정확히 답하기 위해 필요한 하위 질문을 3~5개 도출하세요\n각 하위 질문에 순서대로 답한 뒤 최종 통합 답변을 제시하세요\n질문 : 우리 회사가 베트남에 생산 법인을 설립하면 세금, 인력, 물류 측면에서 유리한가요?","kind":"try"},{"id":"d1s68_1","lab":"방법 2 · 전문가 검증 방식","where":"Gemini 새 채팅 (먼저 질문만 → 새 채팅에서 이 프롬프트로 비교)","text":"FTA 전문가처럼 이 문제를 다루세요\n확신이 없는 부분은 가정으로 명시하고\n각 판단의 근거를 함께 제시하면서 단계적으로 결론에 도달하세요\n질문 : FTA 협정세율을 적용하면 무조건 관세가 줄어드나요?","kind":"try"},{"id":"d1s69_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"웹페이지를 열었는데 아래 에러가 났어요.\n바로 고치지 말고, 다음 순서로 해 주세요.\n1. 에러가 무슨 뜻인지 쉬운 말로 한 줄\n2. 원인 후보 3가지\n3. 각 원인을 내가 확인하는 방법 (순서대로)\n4. 가장 가능성 높은 원인의 수정 코드\n에러 :\n'''\nUncaught TypeError: Cannot read properties of null (reading 'addEventListener')\n'''","kind":"vibe"}],"work":["'FTA 적용되나?' 같은 어려운 질문을 쪼개서 확인"],"caution":"에러가 나면 에러 문구를 ''' 안에 그대로 붙이고 쪼개서 확인하게 하면 엉뚱한 수정이 줄어든다."},{"id":"game","group":"pattern2","title":"게임 플레이","en":"Game Play","summary":"목적·규칙·엔딩을 정해 주면 AI가 진행자가 되어 장면별로 주고받는다.","points":["#입력: 게임 목적, 플레이어 할 일, 특징, 장애물, 진행 조건, 엔딩.","#처리: '당신은 텍스트 기반 어드벤처 게임입니다'. #출력: 상태창 · 장면 설명 · 선택지.","'반드시 한 장면씩 진행'을 넣어야 AI가 혼자 끝까지 달리지 않는다.","역할만 바꾸면 협상 연습, 면접 연습, 클레임 대응 연습이 된다."],"prompts":[{"id":"d2s12_0","lab":"1) #입력","where":"Gemini 새 채팅 → [1)+2) 한 번에 복사] 버튼으로 함께 붙여넣기","text":"#입력\n[게임 목적]\n- 외계인 침략 계획을 밝혀내고 저지함으로써 지구를 구하는 게임\n[플레이어가 해야 할 일]\n- 지구의 여러 도시와 외계인 기지를 탐험한다\n- 다양한 NPC들과 상호 작용하고 정보를 수집한다\n- 논리적 사고를 통해 퍼즐을 해결한다\n- 임무 수행에 도움이 될 유용한 아이템을 수집한다\n- 외계인 전투에 참여해 적들을 물리친다\n[플레이어의 특징]\n- 영웅적이고 용감하며, 항상 지구를 구하기 위해 최선을 다한다\n[도전과 장애물]\n- 도시의 위험한 외계 생명체와 마주쳐 싸운다\n- 외계인 기지에 설치된 위험한 함정을 헤쳐 나간다\n- 외계인 지도자와 대결해야 한다\n[게임 진행 조건]\n- 적에게 공격당하면 전투에 참여한다\n- 수집한 아이템을 사용하여 장애물을 극복한다\n- NPC와 상호 작용할 때 대화 옵션을 선택한다\n- 게임 도중 내리는 선택이 이야기와 진행에 영향을 미친다\n- 상태창을 통해 게임 진행 상태가 표시된다\n- 반드시 한 장면씩 진행한다\n[게임 엔딩]\n- 외계인 본거지에 도달하고 최후의 전투에 참여한다","kind":"try","join":true},{"id":"d2s12_1","lab":"2) #처리 · #출력","where":"1)과 함께 붙여넣기 → 번호로 답하며 진행","text":"#처리\n당신은 \"텍스트 기반 어드벤처 게임\"입니다.\n당신의 목표는 외계인의 침략을 저지하고 지구를 안전하게 지키는 게임을 대화 형식으로 제공하는 것입니다.\n상단의 입력 내용을 게임 전체에 반영해 전체 구조를 설계합니다.\n설계 내용을 설명할 필요는 없습니다.\n대화 형식으로 지금부터 게임을 시작합니다.\n#출력\n[상태창]\n[장면 설명]\n[선택지]","kind":"try"},{"id":"d2s13_0","lab":"실습 · 유니콘 나라 동화 게임","where":"Gemini 새 채팅 → 같은 채팅에서 번호로 답하며 진행","text":"#입력\n[주인공] = 서아\n[나이와 성별] = 4살 여아\n[스토리] = 반려견 밀크와 산책하던 주인공이 아기 유니콘을 만나 유니콘 나라를 여행하고 집으로 돌아옵니다\n#처리\n당신은 \"스토리텔링 게임\"입니다. 당신의 목표는 [주인공]이 등장하는 [스토리]를 가진 게임을 제공하는 것입니다.\n이 게임은 [나이와 성별]을 대상으로 하며, 반드시 어떠한 폭력성도 없으며, 안전하고 행복한 결말을 맞이해야 합니다.\n전체 게임은 5분 이내에 완료됩니다.\n각 장면에는 선택지가 제공되고, 플레이어가 선택할 때까지 대기합니다.\n반드시 한 장면씩 진행합니다.\n이러한 규칙을 기반으로 당신의 상상력을 발휘하여 게임의 전체 구조를 설계합니다.\n설계 내용을 설명할 필요는 없습니다.\n대화 형식으로 지금부터 게임을 시작합니다.","kind":"try"},{"id":"d2s15_0","lab":"실습 · 까다로운 바이어와 협상하기","where":"Gemini 새 채팅 → 같은 채팅에서 영어·한국어로 답하며 진행","text":"지금부터 무역 협상 롤플레이 게임을 합니다.\n#역할\n- 당신: 베트남 식품 유통회사 구매 담당 \"Mr. Nam\" (가격에 매우 까다로움)\n- 나: 한국 라면 수출회사 영업 담당\n#규칙\n- 한 번에 한 턴씩, 당신이 먼저 말을 겁니다\n- 매 턴 끝에 [상태창] 표시: 신뢰도(0~100), 현재 제안 단가, 남은 턴\n- 총 5턴, 단가를 $0.80 이상으로 지키면서 계약하면 승리\n- 게임이 끝나면 내 협상에서 잘한 점 2개, 아쉬운 점 2개 피드백","kind":"try"},{"id":"d2s16_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"아래 규칙으로 브라우저에서 하는 텍스트 어드벤처 게임을 만들어 주세요\n#규칙\n- 주제: 부산항에서 수출 컨테이너가 사라진 미스터리\n- 장면마다 설명 + 선택지 버튼 3개\n- 화면 위에 상태창 (체력, 모은 단서 수)\n- 5장면 안에 엔딩, 마지막에 \"다시 하기\" 버튼\n#출력\nindex.html 한 파일 (HTML·CSS·JavaScript)","kind":"vibe"}],"work":["협상 롤플레이: AI가 '단가를 깎으려는 까다로운 바이어'","신입 교육 퀴즈: 선택형 통관 시나리오","면접 연습: AI가 무역회사 면접관, 한 번에 질문 하나씩"],"extra":{"title":"게임 직접 만들기 (Claude)","prompts":[{"id":"d2s18_0","lab":"STEP 1 · 역질문으로 기획","where":"Claude 새 채팅에 붙여넣기 → 질문마다 같은 채팅에 답하기","text":"저는 브라우저에서 하는 간단한 웹 게임을 만들고 싶어요.\n만들고 싶은 게임: (예: 무역 용어 퀴즈 배틀)\n바로 만들지 말고, 좋은 게임을 만들기 위해 필요한 것을\n한 번에 하나씩 질문해 주세요. (최대 5개)\n질문마다 고를 수 있는 보기 ①②③을 같이 주세요.\n질문이 끝나면 지금까지 답을 \"게임 설계서\" 표로 정리만 해 주세요.","kind":"try"},{"id":"d2s19_0","lab":"STEP 2 · 게임 만들기 (빈칸 채우기)","where":"같은 채팅에 이어서 (STEP 1 채팅) · 처음이면 Claude 새 채팅","text":"#역할\n초보자를 돕는 친절한 웹 게임 개발자\n#게임\n- 이름: (           )\n- 목표: (예: 10문제 중 많이 맞히기)\n- 규칙: (예: 4지선다, 한 문제에 15초)\n- 점수: (예: 정답 +10점, 오답 0점)\n- 끝: (예: 10문제 후 점수와 \"다시 하기\" 버튼)\n#화면\n- 큰 글씨, 큰 버튼, 모바일에서도 잘 보이게\n- 정답이면 초록색, 오답이면 빨간색으로 잠깐 표시\n#제한\n> HTML·CSS·JavaScript 한 파일, 외부 라이브러리 금지\n#출력\nindex.html 전체 코드 + 게임 방법 3줄","kind":"try"},{"id":"d2s20_0","lab":"고치기 · 수정 요청 틀","where":"같은 채팅에 이어서 (게임 만든 채팅)","text":"[반드시] 지금 게임의 규칙과 점수 방식은 절대 바꾸지 마세요\n[고칠 것]\n1. (예: 오답일 때 정답이 무엇인지 2초 동안 보여 주기)\n2. (예: 시작 화면에 \"게임 방법\" 버튼 추가)\n[출력] 바뀐 부분 2줄 설명 + 전체 코드","kind":"try"},{"id":"d2s20_1","lab":"버그가 났을 때","where":"같은 채팅에 이어서","text":"게임에서 (어떤 상황)일 때 (무슨 문제)가 생겨요.\n바로 고치지 말고, 원인 후보 3개를 쉬운 말로 먼저 알려 준 다음\n가장 가능성 높은 원인을 고친 전체 코드를 주세요.","kind":"try"},{"id":"d2s21_0","lab":"⏱ 타이머","where":"같은 채팅에 이어서","text":"한 문제(장면)마다 15초 타이머를 넣고, 시간이 끝나면 자동으로 다음으로 넘어가게 해 주세요. 기존 기능은 그대로, 전체 코드로.","kind":"try"},{"id":"d2s21_1","lab":"🏆 최고 기록","where":"같은 채팅에 이어서","text":"게임이 끝나면 지금 점수와 \"최고 기록\"을 같이 보여 주세요. 최고 기록은 새로고침해도 남게 해 주세요. 기존 기능은 그대로, 전체 코드로.","kind":"try"},{"id":"d2s21_2","lab":"📈 난이도","where":"같은 채팅에 이어서","text":"시작 화면에 쉬움·보통·어려움 버튼을 넣고, 난이도에 따라 시간이나 문제가 달라지게 해 주세요. 기존 기능은 그대로, 전체 코드로.","kind":"try"},{"id":"d2s21_3","lab":"🎉 효과","where":"같은 채팅에 이어서","text":"정답이면 화면에 축하 효과(이모지가 튀어 오르기)를, 오답이면 화면이 살짝 흔들리게 해 주세요. 기존 기능은 그대로, 전체 코드로.","kind":"try"},{"id":"d2s21_4","lab":"🎨 테마","where":"같은 채팅에 이어서","text":"게임 디자인을 (예: 항구와 컨테이너 느낌, 파란색·주황색)으로 바꿔 주세요. 글씨와 버튼은 더 크게. 기존 기능은 그대로, 전체 코드로.","kind":"try"},{"id":"d2s21_5","lab":"🧩 문제 추가","where":"같은 채팅에 이어서","text":"무역 용어 문제를 20개 더 만들어서 게임에 넣고, 매번 10개를 무작위로 골라 나오게 해 주세요. 기존 기능은 그대로, 전체 코드로.","kind":"try"},{"id":"d2s22_0","lab":"게임 리뷰 받기 (리플렉션)","where":"Claude 새 채팅 → 친구 게임 코드나 소감 붙여넣기","text":"당신은 게임 기획자이자 까다로운 플레이어입니다.\n아래 게임을 해 본 소감과 코드를 보고\n재미 · 쉬운 규칙 · 디자인 · 버그 4가지를 10점 만점으로 평가하고\n가장 먼저 고치면 좋을 것 1가지를 알려 주세요.\n#소감\n(직접 해 보고 느낀 점 2줄)","kind":"try"}]}},{"id":"refine","group":"pattern2","title":"질문 개선","en":"Question Refinement","summary":"답을 받기 전에 내 질문부터 더 좋은 질문으로 고친다.","points":["아는 사람이 질문도 잘한다. 모르는 분야일수록 질문이 두루뭉술해서 답도 두루뭉술하다.","방법 세 가지: 개선 후 답변 · 여러 버전 제시 후 선택 · 문제(모호함, 잘못된 전제, 빠진 맥락) 진단 먼저.","보내기 전 체크: 대상이 명확한가? 범위가 좁혀졌나? 목적이 있나? 현재 상태가 있나? 잘못된 전제는 없나?"],"prompts":[{"id":"d2s25_0","lab":"방법 1 · 개선 후 답변","where":"참고용 (틀) · 실습은 다음 장","text":"제 질문에 바로 답하지 말고, 먼저 제 질문을 분석해서 더 나은 질문으로 개선해 주세요\n개선된 질문을 보여준 뒤, 그 질문에 스스로 답하세요","kind":"ref"},{"id":"d2s25_1","lab":"방법 2 · 여러 버전 제시","where":"참고용 (틀) · 실습은 다음 장","text":"제 질문을 3가지 다른 방향으로 개선해 주세요\n각 버전이 어떤 목적에 맞는지 설명하고\n제가 선택하면 그 버전으로 답하세요","kind":"ref"},{"id":"d2s25_2","lab":"방법 3 · 문제 진단 먼저","where":"참고용 (틀) · 실습은 다음 장","text":"제 질문의 문제점(모호함, 잘못된 전제, 누락된 맥락)을 먼저 지적하고\n수정된 질문으로 답변하세요","kind":"ref"},{"id":"d2s26_0","lab":"실습 · 단순 개선형","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 질문을 더 명확하고 답변 가능한 상태로 개선한 뒤\n개선된 질문으로 답변하세요\n개선한 이유도 한 줄로 설명하세요\n질문 : \"AI를 무역에 활용하려면 어떻게 해야 하나요\"","kind":"try"},{"id":"d2s27_0","lab":"실습 · 다방향 분기형","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"제 질문을 3가지 다른 해석으로 개선해 주세요\n각 버전이 어떤 상황에 맞는지 설명하고\n제가 고르면 그것으로 답하세요\n질문 : \"수출 자동화는 어떻게 시작하나요?\"","kind":"try"},{"id":"d2s27_1","lab":"실습 · 전제 교정형","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"제 질문에 잘못된 전제나 오해가 있으면\n먼저 그것을 지적하고 교정된 질문으로 다시 물어봐 주세요\n그 다음 교정된 질문에 답하세요\n질문 : \"FTA를 쓰면 관세를 안 내도 되는 건가요?\"","kind":"try"},{"id":"d2s28_0","lab":"실습 · 내 질문 개선하기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"\"Z세대가 좋아할 만한 이벤트 아이디어로 어떤 것들이 있을까요?\"\n이 질문을 더 나은 버전으로 개선해 주세요.\n질문의 풍부한 맥락을 반영해 구체적이고 자세한 질문을 만들어 주세요.","kind":"try"},{"id":"d2s29_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인 → 번호 고르기","text":"\"구구단 웹페이지 만들어 줘\"\n이 요청을 바이브 코딩용으로 더 나은 요청문으로 개선해 주세요.\n빠진 정보(누가 쓰는지, 기능, 화면, 기술)를 채운\n개선 버전 2개를 보여 주세요.\n제가 하나를 고르면, 그 버전으로 코드를 만들어 주세요.","kind":"vibe"},{"id":"d2s30_0","lab":"질문 채점 + 개선","where":"Gemini 새 채팅","text":"내 질문: \"(여기에 내 질문)\"\n아래 5가지 기준으로 내 질문을 각 2점 만점으로 채점해 주세요.\n대상 · 범위 · 목적 · 현재 상태 · 잘못된 전제\n점수표를 보여 준 뒤, 10점 만점짜리 개선 질문 3개를 만들어 주세요.\n그중 가장 좋은 1개에 ★를 붙여 주세요.","kind":"try"}],"work":["상사의 막연한 지시('베트남 시장 좀 알아봐')를 구체적인 조사 질문으로","거래처·관세사 문의 메일 보내기 전에 빠진 정보 점검"]},{"id":"factcheck","group":"pattern2","title":"팩트 체크 목록","en":"Fact Check List","summary":"AI가 스스로 '이건 확인이 필요해요'를 목록으로 뽑게 한다.","points":["환각: AI가 모르는 것을 그럴듯하게 지어내는 것. 숫자, 날짜, 법·제도, 출처가 특히 위험하다.","답변 끝에 확인 목록을 붙이거나, 답하기 전에 틀리기 쉬운 항목을 먼저 예고하게 한다.","🔴 반드시 확인 · 🟡 확인 권장 · 🟢 참고 수준으로 나누거나, 사실마다 신뢰도(%)를 붙이게 한다."],"prompts":[{"id":"d2s33_0","lab":"방법 1 · 답변 후 목록 추가","where":"참고용 (틀) · 실습은 다음 장","text":"아래 주제로 답변을 작성하세요\n답변 마지막에 반드시 아래 형식으로 팩트 체크 목록을 추가하세요\n## 팩트체크 필요항목\n| 항목 | 내용 | 검증 방법 | 신뢰도 |\n\n주제 : 베트남에 화장품을 수출할 때 필요한 인증","kind":"ref"},{"id":"d2s33_1","lab":"방법 2 · 답변 전 위험 예고","where":"참고용 (틀) · 실습은 다음 장","text":"답변을 작성하기 전에, 이 주제에서 틀리기 쉬운 항목이 무엇인지 먼저 나열하세요\n그 항목을 특히 주의하며 답변을 작성하고 마지막에 검증 목록을 제시하세요\n\n주제 : 미국으로 식품을 수출할 때 필요한 절차","kind":"ref"},{"id":"d2s34_0","lab":"실습 · 신호등 검증 목록","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 질문에 답변하세요\n답변 끝에 반드시 팩트 체크 목록을 작성하세요\n팩트체크 목록 형식\n- 🔴반드시 확인 : 틀리면 큰 피해가 생기는 항목\n- 🟡확인 권장 : 바뀔 가능성이 있는 항목\n- 🟢참고 수준 : 개략적으로 맞지만 세부는 다를 수 있는 항목\n\n질문 : \"한미 FTA 적용 시 원산지 증명서 발급 절차는?\"","kind":"try"},{"id":"d2s35_0","lab":"실습 · 신뢰도 점수","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 내용에 대한 답변을 하되\n각 주요 사실에 신뢰도 점수(0~100%)와 그 점수를 준 이유를 함께 표시하세요\n\n형식 : {사실 내용} [신뢰도 : xx%] (이유 : ~)\n질문 : \"베트남 수출 시 주요 인증 요건과 관세율은?\"","kind":"try"},{"id":"d2s36_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"환율을 인터넷에서 받아와 원화를 달러로 바꿔 주는 웹페이지를 만들어 주세요 (HTML 한 파일)\n코드 뒤에 \"제가 직접 확인해야 할 것\" 목록을 붙여 주세요\n- 사용한 외부 서비스(API) 이름·주소와 무료 여부\n- 실제로 동작하지 않을 수 있는 부분\n- 보안상 주의할 점\n각 항목에 🟢확실 🟡확인 권장 🔴꼭 확인 표시를 붙여 주세요","kind":"vibe"},{"id":"d2s37_0","lab":"함정 질문 + 신호등","where":"Gemini 새 채팅","text":"아래 질문에 답한 뒤, 답변의 각 주장 옆에\n🟢확실 🟡확인 필요 🔴틀릴 수 있음 표시를 붙이고\n마지막에 \"질문에 잘못된 전제가 있는지\"도 따로 검토해 주세요.\n질문: 한국-베트남 FTA로 한국산 라면은 베트남에서 관세가 0%이고,\n2025년부터는 원산지 증명서도 필요 없어졌죠? 정확한 내용을 알려 주세요.","kind":"try"}],"work":["관세율·인증·FTA 규정 답변에 '직접 확인할 것' 목록 붙이기","보고서 숫자(수출액, 점유율)마다 출처 확인 표시"],"caution":"목록이 나와도 100%는 아니다. 최종 확인은 반드시 사람이 공식 자료로 한다."},{"id":"meta","group":"pattern2","title":"메타 언어 (나만의 단축어)","en":"Meta Language","summary":"긴 명령을 /요약 같은 짧은 약속어에 담아 두고 쓴다.","points":["① 먼저 단축어 정의를 보내고 ② 그다음부터 단축어만 써서 질문한다. (같은 채팅에서만 기억한다)","/요약, /비교처럼 같은 질문도 단축어에 따라 3줄 또는 표로 나온다.","자주 쓰는 정의는 Claude 프로젝트 지침, Gemini 스킬 등에 넣어 두면 매번 보낼 필요가 없다.","이모지도 약속어가 될 수 있다. 🖨 = 인쇄용 정리, 📧 = 이메일 형식."],"prompts":[{"id":"d2s40_0","lab":"1단계 · 단축어 정의 먼저 보내기","where":"Gemini 새 채팅에 먼저 보내기","text":"이 대화에서 아래 명령어를 사용합니다\n각 명령어의 정의를 정확히 기억하고 실행하세요\n/요약 = 핵심만 3줄, 전문 용어 제거, 무역 실무자 기준, 결론 먼저 -> 이유 순서로 작성\n/코드 = python 작성, 주석 한국어, 예외 처리 포함, 실행 가능한 완성 코드, 설명 없이 코드만 출력\n/비교 = 2~4개 대안을 표로 정리, 항목 : 장점, 단점, 비용, 난이도, 추천 상황, 마지막 행에 종합 추천 추가","kind":"try"},{"id":"d2s40_1","lab":"2단계 · 단축어로 질문","where":"같은 채팅에 이어서 입력","text":"/요약 베트남 FTA 활용 방법 알려줘","kind":"try"},{"id":"d2s40_2","lab":"이어서 해 보기","where":"같은 채팅에 이어서 입력","text":"/비교 베트남 FTA 활용 방법 알려줘","kind":"try"},{"id":"d2s41_0","lab":"1단계 · 정의 보내기","where":"Gemini 새 채팅에 먼저 보내기","text":"#입력\n[독자] = 초등학생\n[단축어1] = \"/유:[단어]:[개수]\"라고 요청하면, [단어]에 대한 [독자]가 이해할 수 있는 유의어 [개수]를 제공하고, 가장 추천하는 유의어를 알려주세요\n[단축어2] = \"/반:[단어]:[개수]\"라고 요청하면, [단어]에 대한 [독자]가 이해할 수 있는 반의어 [개수]를 제공하고, 가장 추천하는 반의어를 알려주세요\n[단축어3] = \"/유반:[단어]:[개수]\"라고 요청하면, [단축어1]과 [단축어2]를 동시에 수행해 주세요\n#처리\n당신은 \"출판사 편집자\"입니다\n당신은 [독자] 대상의 교양 도서를 교정하고 있습니다.\n상단의 내용을 기억하고, 내가 단축어를 제공하면 그에 따라 작업을 수행해 주세요\n내가 단축어를 제공할 때까지 대기합니다","kind":"try"},{"id":"d2s41_1","lab":"2단계 · 사용하기","where":"같은 채팅에 이어서 입력","text":"/유:금일:2","kind":"try"},{"id":"d2s41_2","lab":"더 해 보기","where":"같은 채팅에 이어서 입력","text":"/유반:기쁘다:3","kind":"try"},{"id":"d2s43_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 먼저 보내기 → 같은 채팅에서 \"/설명 (코드 붙여넣기)\"","text":"이 대화에서 아래 명령어를 사용합니다. 정의를 기억하고 실행하세요\n/수정 = 기존 기능은 절대 바꾸지 말 것, 바뀐 부분만 3줄로 설명, 전체 코드 다시 출력\n/설명 = 코드를 초보자용으로 부분별 쉬운 말 설명, 코드는 다시 출력하지 말 것\n/점검 = 버그·보안·모바일 화면 문제를 표로 정리, 고치는 방법 포함\n이해했으면 \"준비 완료\"라고만 답하세요","kind":"vibe"},{"id":"d2s44_0","lab":"1단계 · 내 단축어 정의 (빈칸 채우기)","where":"Gemini 새 채팅에 먼저 보내기","text":"이 대화에서 아래 명령어를 사용합니다. 정의를 기억하고 실행하세요\n/영메일 = 영어 비즈니스 메일, 제목 포함, 5문장 이내, 정중한 톤, 한국어 뜻 아래에\n/쉽게 = (           )\n/( 내가 정한 이름 ) = (           )\n이해했으면 \"준비 완료\"라고만 답하세요","kind":"try"},{"id":"d2s44_1","lab":"2단계 · 써 보기","where":"같은 채팅에 이어서","text":"/영메일 바이어에게 샘플이 오늘 DHL로 출발했다고 알리기","kind":"try"},{"id":"d2s44_2","lab":"3단계 · 섞어 쓰기","where":"같은 채팅에 이어서","text":"/쉽게 인코텀즈 FOB와 CIF 차이","kind":"try"}],"work":["팀 공용 단축어: /메일(영문 비즈니스 메일), /요약(3줄), /번역(영↔한)","/견적 · /클레임 · /인보이스처럼 자주 쓰는 긴 지시를 줄이기"]},{"id":"reflection","group":"pattern2","title":"리플렉션 (자기 검토)","en":"Reflection","summary":"초안 → 스스로 비평 → 개선본. AI가 자기 답을 한 번 고치게 한다.","points":["자기 비평 질문: 가장 약한 부분은? 빠진 내용은? 독자가 오해할 부분은?","점수 방식: 명확성·완결성·정확성·실용성·간결성을 10점 만점으로 매기고 7점 미만은 반드시 고치게 한다.","평가 기준은 내 목적에 맞게 바꿔도 된다."],"prompts":[{"id":"d2s46_0","lab":"방법 1 · 생성 → 비평 → 개선","where":"참고용 (틀) · 실습은 다음 장","text":"아래 작업을 3단계로 수행하세요\n1단계[초안] : 요청에 대한 첫번째 답변 작성\n2단계[비평] : 초안의 약점, 누락, 개선점을 스스로 분석\n3단계[개선] : 비평을 반영한 최종 버전 작성","kind":"ref"},{"id":"d2s46_1","lab":"방법 2 · 반복 정제","where":"참고용 (틀) · 실습은 다음 장","text":"초안을 작성하고 N번 스스로 개선하세요\n각 반복마다 무엇을 왜 바꿨는지 한 줄로 기록하세요","kind":"ref"},{"id":"d2s47_0","lab":"실습 · 3단계 리플렉션","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 요청을 처리하되 반드시 3단계로 진행하세요\n[초안]\n  먼저 최선을 다해 답변을 작성하세요\n[자기 비평]\n  방금 작성한 답변을 검토하고 아래를 솔직하게 답변하세요\n  - 가장 약한 부분은 어디인가요?\n  - 빠뜨린 중요한 내용이 있나요?\n  - 독자가 오해할 수 있는 부분이 있나요?\n[개선본]\n  비평을 반영한 최종 답변을 작성하세요\n\n요청 : \"python으로 엑셀 파일을 읽어 HS Code별로 정렬하는 코드 작성\"","kind":"try"},{"id":"d2s48_0","lab":"실습 · 5가지 기준 평가","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 문서를 작성하고 완성 후 5가지 기준으로 각각 10점 만점 평가를 수행하세요\n점수가 7점 미만인 항목은 반드시 개선하세요\n평가 기준 :\n① 명확성 : 한번에 이해되는가?\n② 완결성 : 필요한 내용이 모두 있는가?\n③ 정확성 : 틀린 내용이 없는가?\n④ 실용성 : 읽은 후 바로 실행할 수 있는가?\n⑤ 간결성 : 불필요한 내용이 없는가?\n\n요청 : \"첫 수출을 준비하는 소기업을 위한 체크리스트 작성\"","kind":"try"},{"id":"d2s49_0","lab":"바이브 코딩에서","where":"코드를 만든 Claude 채팅에 이어서 입력","text":"방금 만든 코드를 스스로 검토해 주세요\n1) 초보 사용자가 헷갈릴 부분\n2) 버그가 날 수 있는 부분\n3) 모바일 화면에서 깨지는 부분\n각 항목을 10점 만점으로 점수를 매기고,\n7점 이하인 항목은 고쳐서 전체 코드를 다시 주세요","kind":"vibe"},{"id":"d2s50_0","lab":"① 초안 쓰기","where":"Gemini 새 채팅","text":"무역회사 신입 공채 자기소개서의 \"지원 동기\" 문단을 써 주세요.\n나: 무역학과 4학년, 베트남 교환학생 6개월, 영어 중급\n분량: 300자","kind":"try"},{"id":"d2s50_1","lab":"② 비평하기","where":"Claude 새 채팅","text":"당신은 무역회사 인사팀장입니다. 아래 글을\n진정성 · 구체성 · 회사와의 연결 · 문장력 4가지로 각 10점 만점 평가하고\n가장 약한 부분 3곳을 \"이렇게 바꾸면 좋다\" 예시와 함께 알려 주세요.\n#글\n(Gemini가 쓴 글 붙여넣기)","kind":"try"}],"work":["제안서·바이어 메일: 초안 → 자기 비평 → 개선본을 한 번에","내가 쓴 글을 넣고 '바이어 입장에서 비평' → 보내기 전 점검"]},{"id":"outline","group":"pattern2","title":"아웃라인 확장","en":"Outline Expansion","summary":"큰 뼈대를 먼저 세우고, 필요한 곳만 골라서 살을 붙인다.","points":["큰 주제를 한 번에 다 써 달라고 하면 얕고 길어진다.","1단계 대주제 아웃라인만 → 2단계 고른 파트 확장 → 3단계 최소 단위까지. 한 번에 다 붙이지 말고 결과를 보며 단계별로 보낸다.","각 파트에 비중(%)과 우선순위를 붙이면 시간과 분량을 어디에 쓸지 보인다."],"prompts":[{"id":"d2s53_0","lab":"1단계 · 대주제 아웃라인만","where":"Gemini 새 채팅","text":"아래 주제의 최상위 구조만 작성하세요\n각 항목의 제목과 한 줄 설명만 포함하세요\n세부 내용은 아직 작성하지 마세요\n주제 : \"무역 실무자를 위한 python 자동화 8주 과정\"","kind":"try"},{"id":"d2s53_1","lab":"2단계 · 선택한 파트 확장","where":"같은 채팅에 이어서 (번호를 골라서)","text":"5주차 상세 아웃라인을 확장하세요\n각 수업의 학습 목표, 실습 내용, 예상 소요 시간을 포함하세요","kind":"try"},{"id":"d2s53_2","lab":"3단계 · 최소 단위까지","where":"같은 채팅에 이어서 입력","text":"3일차 수업의 강의 스크립트와 실습 코드를 완성본으로 작성하세요","kind":"try"},{"id":"d2s54_0","lab":"실습 · 비중 아웃라인","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 교육 과정의 아웃라인을 작성하되\n각 파트에 전체 대비 비중(%)과 우선순위를 함께 표시하세요\n조건\n- 실습 코드가 이론 설명보다 비중이 높아야 한다\n- 수강생 기준 : python 기초 수료자\n- 총 교육 시간 : 40시간\n주제 : \"무역 데이터 자동화 심화 과정\"","kind":"try"},{"id":"d2s55_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인 → 번호 골라 이어서","text":"\"수출 바이어 관리 웹앱\"을 만들려고 해요. 아직 코드는 쓰지 마세요.\n1단계: 필요한 화면과 기능을 아웃라인(대주제 → 소주제)으로만 보여 주세요.\n각 기능에 [필수 / 나중에] 표시와 만드는 순서를 붙여 주세요.\n제가 번호를 고르면, 그 화면 하나만 코드로 만들어 주세요.","kind":"vibe"},{"id":"d2s56_0","lab":"1단계 · 아웃라인만","where":"Gemini 새 채팅","text":"주제: \"우리 조가 베트남에 수출하고 싶은 한국 제품 소개\"\n5분 발표 자료의 아웃라인을 대주제 4~5개로만 만들어 주세요.\n각 대주제에 시간 비중(%)을 붙여 주세요. 아직 내용은 쓰지 마세요.","kind":"try"},{"id":"d2s56_1","lab":"2단계 · 하나 펼치기","where":"같은 채팅에 이어서","text":"2번 대주제를 슬라이드 3장으로 확장해 주세요.\n장마다: 제목 / 핵심 문장 1개 / 넣을 그림·표 아이디어","kind":"try"},{"id":"d2s56_2","lab":"3단계 · 발표 대본","where":"같은 채팅에 이어서","text":"확장한 3장의 발표 대본을 써 주세요.\n장마다 40초 분량, 말하듯이 쉬운 문장으로.","kind":"try"}],"work":["보고서·사업계획서: 목차 먼저 → 섹션 하나씩 확장","수출 준비 일정: 큰 단계 → 주차별 할 일","비중(%)으로 발표 시간·분량 배분"]},{"id":"context","group":"pattern2","title":"컨텍스트 관리자","en":"Context Manager","summary":"내 상황을 먼저 고정해서 일반론이 아니라 '내 상황 안의 답'을 받는다.","points":["회사 규모, 예산, 시간, 인력, 그리고 집중할 것과 무시할 것을 정해 준다.","상황 블록을 먼저 보내고 '준비 완료' 답을 받은 뒤 같은 채팅에서 질문한다.","'이 대화에서 원하지 않는 것'을 적어 두면 쓸데없는 제안(예: 큰 시스템 도입)이 빠진다.","DAY 3 정리: 가장 중요한 기술. '매출 올릴 전략 짜 줘'보다 '우리 회사는 지금 이만큼, 매출은 얼마'가 정확한 답을 만든다."],"prompts":[{"id":"d2s58_0","lab":"컨텍스트 선언 블록 (틀)","where":"참고용 (틀) · { } 안을 내 상황으로 채워서 사용","text":"## 상황\n  {지금 처한 구체적 상황}\n## 나의 수준\n  {이 주제에 대한 사전 지식과 경험}\n## 목적\n  {이 답변으로 무엇을 결정하거나 실행할 것인가}\n## 제약\n  {시간, 예산, 인력, 기술적 한계}\n## 이 대화에서 원하지 않는 것\n  {답변에서 제외해야 할 방향이나 내용}","kind":"ref"},{"id":"d2s59_0","lab":"실습 · 이메일 개선","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"#입력\n[이메일] =\n'''\n제목 : [제품명] 출시, 당신의 일상을 변화시킬 혁신적인 기술을 만나보세요!\n안녕하세요, [고객명]님\n여러분의 일상에 혁신을 가져올 새로운 기술, [제품명]이 드디어 출시되었습니다!\n최첨단 기술로 설계된 [제품명]은 당신의 생활을 한 단계 업그레이드해 줄 준비가 되어 있습니다.\n주요 특징 :\n- 초고속 처리 기능으로 시간 절약 가능\n- 사용자 친화적 인터페이스로 누구나 쉽게 사용\n- 지속 가능한 소재 사용으로 환경까지 생각한 디자인\n지금 바로 [웹사이트 링크]를 방문하셔서 자세한 정보를 확인해 보세요.\n[제품명]과 함께라면 당신의 일상이 더욱 특별해질 것입니다.\n감사합니다. [회사명] 드림\n'''\n#처리\n당신은 \"마케팅 전문가\"입니다.\n[이메일] 내용을 전문가의 시각에서 분석하고, 개선된 이메일을 작성해 주세요\n- 고객이 가장 관심을 가질 만한 제품 기능과 혜택에 대한 언급이 충분한지, 감정적 요소가 잘 드러나는지 문제점 위주로 분석하세요\n- 고객의 관심을 끌 수 있는 요소에 초점을 맞추고, 이메일의 길이나 문법적 정확성은 무시하세요\n#출력\n[분석 결과]\n[개선된 이메일]","kind":"try"},{"id":"d2s60_0","lab":"1단계 · 상황 먼저 보내기","where":"Gemini 새 채팅에 먼저 보내기","text":"아래 조건은 이 대화 전체에 적용됩니다\n모든 답변은 이 컨텍스트 안에서만 이루어지게 해 주세요\n## 회사 상황\n- 업종 : 의료기기 중소기업\n- 직원 : 30명, 무역팀 3명\n- 주요 수출국 : 미국(60%), 독일(30%), 기타(10%)\n- 연 수출액 : 약 50억원\n## 기술 환경\n- 현재 시스템 : ERP 없음, 엑셀 중심\n- 개발 인력 : 없음\n- IT 예산 : 월 100만원 이내\n## 절대 제외 사항\n- 대규모 시스템 도입 제안(ERP)\n- 개발자 고용 전제의 솔루션\n- 6개월 이상 구축 기간이 필요한 방안\n이 컨텍스트를 이해했으면 \"준비 완료\"라고만 답하세요","kind":"try"},{"id":"d2s60_1","lab":"2단계 · \"준비 완료\" 후 질문","where":"\"준비 완료\" 답이 오면 같은 채팅에","text":"수출 서류 자동화 방법 알려줘","kind":"try"},{"id":"d2s62_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 먼저 → \"준비 완료\" 후 같은 채팅에서 요청","text":"## 프로젝트 상황\n- 만드는 것: 무역 용어 퀴즈 웹페이지\n- 나의 수준: 코딩 처음, HTML 파일 하나만 다룰 수 있음\n- 기술: HTML·CSS·JavaScript 한 파일, 설치가 필요한 것 금지\n## 원하지 않는 것\n- 서버, 데이터베이스, 로그인 기능\n- 어려운 전문 용어로 된 설명\n이 상황을 이 대화 내내 지켜 주세요. 이해했으면 \"준비 완료\"라고만 답하세요","kind":"vibe"},{"id":"d2s63_0","lab":"상황 블록 (내 걸로 바꾸기)","where":"Gemini 새 채팅 (B) → \"준비 완료\" 후 같은 채팅에 질문","text":"## 상황\n- 대학생, 자취 중, 한 달 용돈 60만 원\n- 아르바이트 주 2회\n## 목적\n- 3개월 안에 50만 원 모으기\n## 제약\n- 식비는 크게 줄이기 어려움\n## 원하지 않는 것\n- 주식·코인 투자 이야기, 뻔한 가계부 앱 추천\n이해했으면 \"준비 완료\"라고만 답하세요","kind":"try"}],"work":["회사 규모·예산·제외 사항을 먼저 고정 → 우리 회사에 맞는 답만","조별 프로젝트: 우리 조 상황을 첫 메시지로 고정"],"caution":"이 상황 블록이 나중에 Claude Code의 CLAUDE.md(프로젝트 설명서)가 된다."},{"id":"infinite","group":"pattern2","title":"무한 생성","en":"Infinite Generation","summary":"고정 틀 + 바뀌는 변수로 결과물을 여러 개 한꺼번에 찍어낸다.","points":["고정 프레임(예: '[수신자]에게 [목적]을 전달하는 영문 이메일')에 변수 조합을 넣는다.","'계속'이라고 하면 하나 더, '멈춰'라고 하면 끝처럼 계속 생성도 가능하다.","연습용 가짜 데이터(더미)를 만들 때 특히 좋다."],"prompts":[{"id":"d2s61_0","lab":"실습 · 무역 이메일 생성기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"**무역 이메일 생성기**\n고정 프레임 :\n  \"[수신자 유형]에게 [목적]을 전달하는 영문 이메일\"\n변수 :\n  {수신자} : 신규 바이어 / 기존 거래처 / 포워더 / 관세사\n  {목적} : 첫 연락 / 견적 요청 / 납기 연장 / 클레임 대응\n  {톤} : 공식적인 / 친근한 / 긴급\n생성 규칙 :\n  3단락 구조, 제목 포함 150단어 이내\n위 변수 조합으로 이메일 4개를 생성해 주세요","kind":"try"}],"work":["바이어 유형 × 목적 × 톤 조합으로 메일 수십 개","퀴즈 문제 30개 같은 더미 데이터"],"caution":"만들어진 이메일은 반드시 눈으로 확인하고 보낸다."},{"id":"frameworks","group":"framework","title":"프레임워크 한눈에","en":"Frameworks","summary":"좋은 프롬프트의 규칙을 영어 첫 글자로 묶은 공식. 외울 필요는 없다.","points":["잘 보면 모두 역할 · 목표 · 상황 · 출력의 조합이다.","정답은 없다. 흐름 잡기 쉬운 CO-STAR를 자주 쓰게 된다. 형식보다 의미를 정확히 전달하는 게 중요하다.","어떤 걸 쓸지 모르겠으면 AI에게 추천받고, 필요한 정보를 하나씩 질문하게 한다."],"blocks":[{"type":"table","head":["이름","구성","이럴 때"],"rows":[["5W1H","누가 · 무엇을 · 언제 · 어디서 · 왜 · 어떻게","상황 정리, 전략·보고서"],["CO-STAR","Context 상황 · Objective 목표 · Style 문체 · Tone 말투 · Audience 대상 · Response 결과물","제안서, 설득하는 글"],["FOCUS","Function 역할 · Objective 목표 · Context 상황 · Utility 활용처 · Specifications 세부 조건","마케팅 메시지·캠페인"],["ROSES","Role 역할 · Objective 목표 · Scenario 시나리오 · Expected Solution 기대 결과 · Steps 단계","협상, 시뮬레이션"],["RISEN","Role 역할 · Instructions 지시 · Steps 단계 · End goal 최종 목표 · Narrowing 범위 좁히기","문제 해결 절차, 코드 요청"],["BAB","Before 이전 · After 이후 · Bridge 연결 방법","성공 스토리, 홍보 글"]]}],"prompts":[{"id":"d2s71_0","lab":"실습 · 비교·추천받기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"5W1H, CO-STAR, FOCUS, ROSES, RISEN, BAB 6가지 프롬프트 프레임워크를 비교해서\n각각 어떤 상황에 쓰는 것이 가장 좋은지 표로 정리해 주세요.\n무역 업무 예시를 하나씩 넣어 주세요.","kind":"try"},{"id":"d2s71_1","lab":"실습 · 역질문으로 고르기","where":"Gemini 새 채팅 → AI 질문에 같은 채팅에서 답하기","text":"저는 (해결하고 싶은 문제)를 하려고 합니다.\n바로 답하지 말고, 어떤 프레임워크로 질문하는 것이 좋을지 먼저 추천하고\n그 프레임워크에 필요한 정보를 저에게 하나씩 질문해 주세요.","kind":"try"},{"id":"d2s72_0","lab":"바이브 코딩에서","where":"Claude 새 채팅에 붙여넣기 → 결과 확인","text":"R (역할): 비전공자를 돕는 친절한 웹 개발자\nI (지시): 바이어 연락처 메모장 웹페이지를 만들어 주세요\nS (단계): 1) 화면 구성 설명 3줄 2) 코드 작성 3) 사용 방법 3줄\nE (목표): 이름·국가·메모를 입력해 저장하고 아래 표로 보기\nN (제한): HTML 한 파일, 외부 라이브러리 금지, 화면은 한국어","kind":"vibe"},{"id":"d2s73_0","lab":"맞혔으면 직접 써 보기","where":"Gemini 새 채팅","text":"상황: (고른 상황 카드)\n프레임워크: (정답 프레임워크)\n이 프레임워크의 각 항목을 저에게 하나씩 질문해서 채운 다음,\n완성된 프롬프트와 그 결과물을 함께 보여 주세요.","kind":"try"}],"work":["CO-STAR: 바이어 설득 제안서 · ROSES: 가격 협상 전략","5W1H: 시장 진출 계획 · BAB: 수출 성공 사례 소개글","팀에서 프레임워크 하나를 정해 두면 보고서 형식이 통일"]},{"id":"fw-5w1h","group":"framework","title":"5W1H","en":"Who · What · When · Where · Why · How","summary":"육하원칙에 맞춰 정보를 주면 답도 그 안에서 정확해진다.","points":["6개를 다 채우지 않아도 된다. 2~3개만 써도 효과가 있다."],"prompts":[{"id":"d2s66_0","lab":"실습 · 5W1H","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"#입력\n[who] = 중소 제조업체 (직원 30명)\n[what] = 친환경 포장재를 유럽 시장에 수출\n[when] = 2026년 하반기부터 본격 수출 시작\n[where] = 독일, 프랑스, 네덜란드를 1차 타겟\n[why] = EU의 플라스틱 규제 강화로 친환경 포장재 수요 급증\n[how] = 현지 유통사 파트너십을 통한 B2B 판매\n#처리\n당신은 \"EU 시장 진출 전문 컨설턴트\"입니다\n상단의 5W1H 정보를 바탕으로 다음을 작성하세요\n1. 시장 진입 전략 (3가지 옵션 비교)\n2. 필수 인증 및 규제 대응 (CE마크 등)\n3. 바이어 발굴 및 파트너십 전략\n4. 6개월 실행 로드맵\n#출력\n[전략보고서] = 각 섹션별 300~500 단어","kind":"try"}]},{"id":"fw-costar","group":"framework","title":"CO-STAR","en":"Context · Objective · Style · Tone · Audience · Response","summary":"제안서·마케팅처럼 설득하는 글에 가장 많이 쓰는 공식.","points":["영문 결과가 나오면 '한국어로 번역해 줘'로 내용을 확인한다."],"prompts":[{"id":"d2s67_0","lab":"실습 · CO-STAR","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"Context : 미국 대형 유통사가 K-뷰티 제품 소싱을 고려 중입니다. 현재 중국 공급사와 거래 중이나, 품질 이슈로 대안을 찾고 있습니다\nObjective : 우리 회사를 신규 공급사로 선정하도록 설득하는 제안서를 작성하세요\nStyle : 전문적이고 데이터 기반의 비즈니스 문서\nTone : 자신감 있으면서도 파트너십을 강조하는 협력적 톤\nAudience : 미국 유통사의 소싱 디렉터 (40대, 15년 경력)\nResponse :\n * 영문 Business Proposal 형식\n * 총 800~1000 단어\n * Executive Summary, Company Profile, Product Advantages, Quality Assurance 포함\n * 품질 비교 데이터 및 인증서 리스트 포함","kind":"try"}],"caution":"데이터·인증서는 AI가 지어낼 수 있으니 실제 자료로 바꿔야 한다."},{"id":"fw-focus","group":"framework","title":"FOCUS","en":"Function · Objective · Context · Utility · Specifications","summary":"어디에 쓸지(Utility)와 세부 조건(Specifications)이 들어간 마케팅용 공식.","points":["버전 3개를 받는 건 대안 패턴과 같은 원리다."],"prompts":[{"id":"d2s68_0","lab":"실습 · FOCUS","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"Function : 당신은 글로벌 B2B 마케팅 전문가입니다. 신규 바이어 발굴을 위한 LinkedIn 메시지를 작성하세요\nObjective : 타겟 바이어의 답장률을 30% 이상으로 높이는 것이 목적\nContext : 우리 회사는 산업용 센서를 제조하며, 독일 자동차 부품 업체를 타겟으로 합니다. 가격 경쟁력과 빠른 납기가 강점입니다\nUtility : LinkedIn 메시지 캠페인에 활용됩니다\nSpecifications :\n - 메시지 길이 : 150~200단어\n - 영문 작성\n - 3가지 버전(공식적 / 친근함 / 문제 해결 중심)\n - 각 버전마다 제목 포함","kind":"try"}]},{"id":"fw-roses","group":"framework","title":"ROSES","en":"Role · Objective · Scenario · Expected Solution · Steps","summary":"숫자로 된 시나리오를 주고 협상·시뮬레이션을 미리 연습한다.","points":["FOB = 배에 실어 주는 것까지 판매자가 책임지는 가격 조건.","1차에 희망가보다 높게 부르는 이유는 깎아 주는 것처럼 보이게 하기 위해서다."],"prompts":[{"id":"d2s69_0","lab":"실습 · ROSES","where":"Gemini 새 채팅 (Claude에서도 비교)","text":"Role : 당신은 국제 무역 협상 전문가입니다\nObjective : 미국 바이어와의 가격 협상에서 FOB $50/unit을 달성해야 합니다\nScenario :\n * 바이어 첫 제시가 : $40/unit\n * 우리 희망가 : $50/unit\n * 시장 평균가 : $45/unit\n * 바이어 연간 예상 물량 : 50,000 units\n * 경쟁사(중국 업체) 제시가 : $42/unit\nExpected Solution :\n * 협상 전략 3단계\n * 각 단계별 제시 가격 및 조건\n * 양보 vs 가치 강조 밸런스\n * 최종 합의 시나리오\nSteps :\n 1. 현재 상황 분석\n 2. 가치 제안 준비 (품질, 납기, 인증)\n 3. 1차 협상 : 품질 차별화 강조, $55 제시\n 4. 2차 협상 : 물량 증가 시 단계별 할인 제안 ($55-$53-$50)\n 5. 계약서 작성 및 후속 조치\n#출력\n[협상 스크립트] = 각 단계별 대화 예시 (영문)\n[체크리스트] = 협상 전 준비 사항","kind":"try"}]},{"id":"fw-risen","group":"framework","title":"RISEN","en":"Role · Instructions · Steps · End goal · Narrowing","summary":"역할·지시·단계·목표·제한 다섯 칸. 코드 요청에 특히 잘 맞는다.","points":["다섯 칸만 채우면 빠지는 정보가 없다."],"prompts":[{"id":"d2s70_0","lab":"RISEN · 무역 분쟁 해결 (빈칸 채우기)","where":"빈칸을 채워서 Gemini 새 채팅에","text":"Role : 당신은 국제 무역 분쟁 해결 전문가입니다\nInstructions : 바이어가 품질 불량을 이유로 대금 지급을 거부한 상황의 해결 방안을 제시하세요\nSteps : 1. 사실 확인 2. 증거 정리 3. 협상 4. 중재·소송 검토\nEnd goal : 거래 관계를 유지하면서 손실을 최소화\nNarrowing : 중소기업 기준, 변호사 비용 최소화, A4 1장 분량","kind":"try"},{"id":"d2s70_2","lab":"실습 · 내 상황으로 빈칸 만들기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"RISEN 프레임워크로 \"(내가 해결하고 싶은 문제)\" 프롬프트를 만들어 주세요. 각 칸을 채운 완성 프롬프트로 보여주세요.","kind":"try"}]},{"id":"fw-bab","group":"framework","title":"BAB","en":"Before · After · Bridge","summary":"이전 → 이후 → 그 사이를 잇는 과정. 성공 스토리·홍보 글에 쓴다.","points":[],"prompts":[{"id":"d2s70_1","lab":"BAB · 수출 성공 스토리 (빈칸 채우기)","where":"빈칸을 채워서 Gemini 새 채팅에","text":"Before : 국내 판매만 하던 직원 20명 김 가공 회사, 매출 정체\nAfter : 2년 만에 미국·동남아 수출로 매출 40% 증가\nBridge : 이 변화를 만든 과정(시장 조사, 인증, 바이어 발굴, 온라인 마케팅)을 홍보용 스토리로 작성해 주세요","kind":"try"}]},{"id":"multi","group":"advanced","title":"다중 관점","en":"Multi-Perspective","summary":"한 사람의 눈이 아니라 여러 사람의 눈으로 동시에 본다.","points":["관점 하나만 보면 무언가 빠진다. 전문가만 보면 감성이, 낙관론만 보면 리스크가 빠진다.","여러 관점이 만나면 충돌하는 지점(진짜 문제), 동의하는 지점(확실한 사실), 보완하는 지점(완전한 해결책)이 보인다.","방법: 병렬 관점 소환 · 대화(토론) 시뮬레이션 · 레이어(층) 분석."],"blocks":[{"type":"table","head":["차원","뜻","예시"],"rows":[["① 이해관계자","관련된 사람들의 서로 다른 입장","대표 · 팀장 · 팀원 · 외주업체"],["② 전문 분야","다른 학문과 직종의 시각","심리학 · 경제학 · 디자인"],["③ 시간","과거 · 현재 · 미래","5년 전 · 지금 · 5년 후"],["④ 가치관","다른 철학과 우선순위","성장 우선 · 안정 우선"],["⑤ 문화·맥락","다른 환경과 배경","한국 · 베트남 · 필리핀 소비자"]]}],"prompts":[{"id":"d3s10_0","lab":"방법 1 · 병렬 관점 소환","where":"참고용 (틀) · 실습은 다음 장","text":"아래 주제를 {N가지 관점}에서 동시에 분석하세요\n각 관점은 독립적으로 분석하되 마지막에 관점들이 만나는 교차점을 찾아주세요","kind":"ref"},{"id":"d3s10_1","lab":"방법 2 · 대화 시뮬레이션","where":"참고용 (틀) · 실습은 다음 장","text":"{관점A}, {관점B}, {관점C}가\n같은 테이블에 앉아 이 주제를 토론합니다\n각자의 주장, 반론, 그리고 결론을 써주세요","kind":"ref"},{"id":"d3s10_2","lab":"방법 3 · 레이어 분석","where":"참고용 (틀) · 실습은 다음 장","text":"같은 주제를 {레이어1}에서 {레이어N}까지\n겹겹이 쌓아가며 분석하세요\n아래 층위가 위 층위를 어떻게 규정하는지 보여주세요","kind":"ref"},{"id":"d3s11_0","lab":"실습 · 이해관계자","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 상황에 관련된 4명의 이해관계자를 동시에 분석하세요\n각 이해관계자에 대한 설명 :\n- 가장 원하는 것 (핵심 욕구)\n- 가장 두려워하는 것 (핵심 공포)\n- 공개적으로 말하는 것 vs 속으로 생각하는 것\n- 이 상황에서 갖는 협상력\n마지막에 :\n- 모두가 동의할 수 있는 최소 공통점\n- 가장 큰 갈등 지점\n- 현실적 합의 가능 경로\n\n상황 : 중소기업이 수출 자동화 시스템 도입을 추진 중인 상황\n이해관계자 : 대표, 무역팀장, 팀원 2명, IT 외주업체","kind":"try"},{"id":"d3s12_0","lab":"실습 · 전문 분야 렌즈","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 문제를 5가지 전문 분야의 렌즈로 동시에 분석하세요\n각 분야가 이 문제를 어떻게 정의하고 어떤 해결책을 제안하는지 보여주세요\n분야 : 심리학 / 경제학 / 시스템 공학 / 인류학 / 게임 디자인\n문제 : \"무역 팀이 새로운 자동화 도구 도입 후 3개월이 지나도 제대로 활용하지 못한다\"","kind":"try"},{"id":"d3s13_0","lab":"실습 · 시간 레이어","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 주제를 3개의 시간 레이어에서 동시 분석하세요\n각 레이어가 다음 레이어에 어떤 영향을 주는지 연결하세요\n\n레이어 1 - 과거 (5년 전) :\n 당시 사람들은 무엇을 알고, 무엇을 몰랐나?\n레이어 2 - 현재 :\n 과거의 결정이 현재에 어떤 모습으로 나타나는가?\n 지금 진짜 문제는 무엇인가?\n레이어 3 - 미래 (향후 5년 후) :\n 지금 선택이 미래에 어떤 모습으로 누적되는가?\n 어떤 결정을 지금 내려야 미래가 달라지는가?\n\n주제 : \"한국 중소기업의 무역 디지털 격차\"","kind":"try"},{"id":"d3s14_0","lab":"실습 · 문화권 관점","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"아래 제품을 4가지 문화권 관점에서 동시에 분석하세요\n각 문화권의 소비자가 이 제품을 어떻게 받아들일지, 주의할 점은 무엇인지 보여주세요\n문화권 : 한국 / 필리핀 / 베트남 / 미국\n제품 : 한국산 K-뷰티 선크림\n마지막에 모든 문화권에서 통하는 공통 마케팅 포인트를 정리하세요","kind":"try"},{"id":"d3s15_0","lab":"바이브 코딩에서","where":"Claude 새 채팅","text":"아래 웹페이지를 4명의 관점에서 동시에 리뷰해 주세요\n1) 코딩을 모르는 50대 사용자: 쓰기 쉬운가?\n2) UI 디자이너: 보기 좋고 정돈됐나?\n3) 개발자: 버그·느려질 부분은?\n4) 보안 전문가: 위험한 부분은?\n각 관점에서 문제 2개씩 → 마지막에 \"가장 먼저 고칠 3가지\"를 우선순위로\n'''\n(내 HTML 코드 붙여넣기 · 없으면 \"무역 용어 퀴즈 페이지\"라고 쓰기)\n'''","kind":"vibe"},{"id":"d3s16_0","lab":"실습 · 3인 토론 시뮬레이션","where":"Gemini 새 채팅 → 같은 채팅에서 사회자로 진행","text":"지금부터 토론 쇼를 진행합니다. 나는 사회자입니다.\n주제: (예: 대학생 때는 아르바이트보다 공부가 우선이다)\n토론자 3명:\n- 찬성: 20년 차 교수 \"박교수\"\n- 반대: 자수성가한 사업가 \"김대표\"\n- 중립: 현실적인 취업 컨설턴트 \"이코치\"\n#규칙\n- 한 번에 한 라운드씩, 토론자마다 2~3문장\n- 서로의 말에 반박하며 진행\n- 매 라운드 끝에 \"사회자님, 다음 질문을 해 주세요\"로 멈추기\n- 내가 \"결론\"이라고 하면 세 사람이 합의할 수 있는 점 3가지 정리","kind":"try"}],"work":["수출 계약 조건을 바이어 · 물류 · 재무 · 법무 관점으로 동시에 검토","신제품을 현지 소비자 · 경쟁사 · 유통사 입장에서 미리 반응 예측","회의 전에 '반대할 사람의 속마음'을 미리 준비"]},{"id":"deliberate","group":"advanced","title":"심사숙고 (CoT)","en":"Deliberate Thinking · Chain of Thought","summary":"즉답은 '확률', 생각은 '추론'. 바로 답하지 말고 단계별로 생각하게 한다.","points":["깊게 생각하게 하는 4가지 장치: ① 답 전에 먼저 생각하기 ② 건너뛸 수 없는 중간 단계 ③ 답 뒤에 자기 검증 ④ 아는 것과 모르는 것 구분.","CoT(Chain of Thought, 생각의 사슬): 고리를 이어 가듯 단계적으로 추론한다. 중간 결론을 보여 달라고 하면 과정이 보인다.","AI는 맞장구를 잘 친다. 좋은 말만 듣지 않으려면 반론을 먼저 요청한다.","Gemini·ChatGPT의 '생각 모드', '심층 분석'도 같은 원리다."],"prompts":[{"id":"d3s20_0","lab":"일반 질문","where":"Gemini 새 채팅 ①","text":"우리 회사가 베트남에 진출해야 할까?","kind":"try"},{"id":"d3s20_1","lab":"실습 · 심사숙고 질문 (CoT)","where":"Gemini 새 채팅 ② → ①과 비교","text":"우리 회사가 베트남에 진출해야 할지 단계별로 생각하면서 판단해줘\n각 단계에서 내린 중간 결론을 보여줘","kind":"try"},{"id":"d3s21_0","lab":"실습 · 반론 먼저","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"\"베트남에 화장품을 수출하면 무조건 성공한다\"는 내 주장에 대해\n먼저 가장 강력한 반론 3가지를 제시하고,\n그 반론을 고려했을 때 내가 준비해야 할 것을 단계별로 정리해줘","kind":"try"},{"id":"d3s22_0","lab":"바이브 코딩에서","where":"Claude 새 채팅","text":"무역 용어 퀴즈 웹앱에 \"점수 저장\" 기능을 넣고 싶어요.\n바로 코드를 쓰지 말고 단계별로 생각해 주세요.\nStep 1: 저장 방법 후보 3가지 (쉬운 말로)\nStep 2: 나는 코딩 초보, HTML 한 파일만 다룸 → 각 후보의 난이도\nStep 3: 각 후보의 가장 큰 반대 의견 1개\nStep 4: 중간 결론들을 바탕으로 최종 추천 1개 + 이유\n그다음에 추천한 방법으로 코드를 만들어 주세요.","kind":"vibe"},{"id":"d3s23_0","lab":"A · 즉답만 시키기","where":"Gemini 새 채팅 ①","text":"아래 3문제에 설명 없이 숫자만 바로 답하세요.\n1) 배트와 공을 합쳐 1,100원. 배트는 공보다 1,000원 비싸다. 공은 얼마?\n2) 기계 5대가 5분에 부품 5개를 만든다. 기계 100대가 부품 100개를 만들려면 몇 분?\n3) 연못의 연잎이 매일 2배로 늘어 48일 만에 연못을 다 덮는다. 절반을 덮는 건 며칠째?","kind":"try"},{"id":"d3s23_1","lab":"B · 생각하게 하기","where":"Gemini 새 채팅 ② (새 채팅)","text":"위 3문제를 단계별로 생각하며 풀고, 각 문제마다 \"흔히 하는 실수\"도 알려 주세요.","kind":"try"}],"work":["진출 국가 선택, 가격 결정처럼 틀리면 비싼 판단은 단계별 + 중간 결론","'반론 먼저'로 내 계획의 약점부터 듣기"]},{"id":"ape","group":"advanced","title":"APE (프롬프트를 만드는 프롬프트)","en":"Automatic Prompt Engineer","summary":"AI가 후보를 여러 개 만들고, 점수를 매기고, 가장 좋은 것끼리 합친다.","points":["기법을 일일이 기억하지 않아도 '이런 일을 하고 싶어'만 주면 AI가 최적의 프롬프트를 만든다.","4단계: ① 서로 다른 전략으로 후보 10개 ② 명확성·완전성·실행 가능성·품질 유도력 각 25점 채점 ③ 상위 3개 결합 ④ 최적 프롬프트 + 이유 + 주의 사항.","코딩용은 '바로 실행되는가'가 가장 중요해서 점수 비중을 다르게 준다 (실행 30 · 완전 25 · 가독 25 · 확장 20).","아래 '프롬프트 생성기'에서 작업 3줄만 넣으면 바로 APE 프롬프트를 만들 수 있다."],"blocks":[{"type":"table","head":["전략","예시 문장","전략","예시 문장"],"rows":[["역할 부여형","\"당신은 ○○ 전문가입니다\"","독자 설정형","\"○○을 모르는 사람도 이해하도록\""],["단계별 지시형","\"step 1 : … step 2 : …\"","형식 지정형","\"결과를 [형식]으로 출력하세요\""],["예시 포함형","\"다음과 같이 해주세요 [예시]\"","품질 기준형","\"○○ 기준으로 90점 이상이 되도록\""],["제약 명시형","\"반드시 ~하되, ~하지 마세요\"","역방향형","\"나쁜 예시는 ~, 좋은 예시는 ~\""],["목적 중심형","\"최종 목표는 ~이며…\"","메타 지시형","\"이 작업의 본질은 ~이며…\""]]}],"prompts":[{"id":"d3s28_0","lab":"실습 · APE 마스터 프롬프트 (1)","where":"","text":"#역할\n당신은 프롬프트 엔지니어링 전문가입니다\n주어진 작업에 대해 최적의 프롬프트를 자동으로 생성, 평가, 개선합니다\n##APE 실행 순서\n### step 1 : 후보 프롬프트 생성\n아래 작업을 위한 프롬프트 후보 10개를 생성합니다\n각 후보는 서로 다른 전략을 사용해야 합니다\n전략 유형\n- 역할 부여형 : \"당신은 xxx 전문가입니다\"\n- 단계별 지시형 : \"step 1 : ... step 2 : ...\"\n- 예시 포함형 : \"다음과 같이 ~해주세요 [예시]\"\n- 제약 명시형 : \"반드시 ~하되, ~하지 마세요\"\n- 목적 중심형 : \"최종 목표는 ~이며 ...\"\n- 독자 설정형 : \"~을 모르는 사람도 이해하도록\"\n- 형식 지정형 : \"결과를 [형식]으로 출력하세요\"\n- 품질 기준형 : \"~한 기준으로 평가했을 때 90점 이상...\"\n- 역방향형 : \"나쁜 예시는 ~이고, 좋은 예시는 ~\"\n- 메타 지시형 : \"이 작업의 본질은 ~이며 ...\"\n### step 2 : 각 후보 자체 평가\n각 프롬프트에 대해 아래 기준으로 점수 매기기 :\n명확성(0~25점) : 지시가 모호하지 않은가\n완전성(0~25점) : 필요한 정보가 다 있는가\n실행 가능성(0~25점) : AI가 바로 실행하는가\n품질 유도력(0~25점) : 높은 품질의 결과를 이끌어 내는가\n총 100점 만점\n### step 3 : 상위 3개 선택 후 교차 최적화\n상위 3개 프롬프트의 강점을 결합하여 최종 최적 프롬프트 1개 생성\n### step 4 : 최적 프롬프트 출력\n- 최적 프롬프트 전문\n- 왜 이것이 최선인지 설명\n- 사용 시 주의 사항","kind":"try","join":true},{"id":"d3s28_1","lab":"(2) 작업 입력 · 클레임 답장","where":"Gemini 새 채팅 → [(1)+(2) 한 번에 복사]로 (1)과 함께 붙여넣기","text":"### 작업 입력\n작업 : {고객 클레임 이메일 답장 작성}\n원하는 결과물 : {고객이 화가 풀리고 우리 회사를 신뢰하게 하는 답장}\n피해야 할 것 : {방어적 태도, 책임 회피, 형식적인 사과}","kind":"try"},{"id":"d3s29_0","lab":"실습 · 코딩 APE 프레임워크","where":"Claude 새 채팅 → 나온 최적 프롬프트를 새 채팅에서 실행","text":"# 코딩 작업 APE 프레임워크\n## 코딩 프롬프트 품질 기준\n실행 가능성 (30) : 코드가 바로 실행되는가?\n완전성 (25) : 예외 상황, 에러 처리를 포함하는가?\n가독성 (25) : 주석과 변수명이 이해하기 쉬운가?\n확장성 (20) : 나중에 수정하기 쉬운 구조인가?\n## 코딩 APE 프롬프트 템플릿\n다음 코딩 작업을 위한 최적 프롬프트를 생성하세요\n작업 : {파이썬으로 엑셀 파일을 읽는 코드}\n언어/프레임워크 : {python}\n제약 : {pandas 라이브러리 사용}\n경험 수준 : {초보}\n## APE 평가 기준\n1. 코드가 처음부터 실행 가능한가 (즉시 실행 vs 수정 필요)\n2. 에러 처리가 포함되어 있는가?\n3. 주석으로 학습 포인트가 설명되어 있는가?\n4. 유사 케이스에 응용 가능한가?","kind":"try"},{"id":"d3s31_0","lab":"바이브 코딩에서","where":"Claude 새 채팅 → 최종 프롬프트를 복사해 다른 새 채팅에서 실행","text":"#작업\n바이브 코딩용 최적 프롬프트를 만들어 주세요 (APE 방식)\n- 만들 것: (예: 수출 일정 체크리스트 웹페이지)\n- 사용자: 코딩을 처음 하는 무역학과 대학생\n- 조건: HTML 한 파일, 외부 라이브러리 금지\n#순서\n1) 서로 다른 전략의 후보 프롬프트 3개\n2) 실행 가능성·완전성·쉬운 설명 기준으로 각 점수\n3) 장점을 합친 최종 프롬프트 1개를 코드 블록으로","kind":"vibe"},{"id":"d3s32_0","lab":"B · 빠른 APE","where":"Gemini 새 채팅 (A와 다른 새 채팅)","text":"작업: (           )\n원하는 결과물: (           )\n피해야 할 것: (           )\n이 작업을 위한 프롬프트 후보 5개를 서로 다른 전략으로 만들고\n명확성·완전성·실행 가능성·품질 유도력 각 25점으로 채점한 뒤\n가장 좋은 최종 프롬프트 1개만 코드 블록으로 보여 주세요.\n그리고 그 최종 프롬프트를 바로 실행한 결과물도 보여 주세요.","kind":"try"}],"work":["반복 업무(클레임 답장, 견적 안내, 바이어 첫 메일)용 최적 프롬프트를 만들어 팀이 같이 쓰기","신입이 와도 같은 품질 → 업무 매뉴얼 역할"],"link":["generator","프롬프트 생성기로 바로 만들기"]},{"id":"project","group":"advanced","title":"Claude 프로젝트로 나만의 AI","en":"Instructions + Knowledge","summary":"지침(역할·규칙) + 자료(파일) = 매번 붙여넣지 않고 계속 쓰는 나만의 AI.","points":["프로젝트 지침: 역할, 매번 지킬 규칙, 작업 순서, 출력 형식, 금지 사항 → 모든 채팅에 자동 적용.","프로젝트 지식: 회사 소개, 제품 표, 예시 메일, 용어집, 코딩 규칙 → 모든 채팅이 참고.","새 채팅(세션): 이번에만 할 일. 채팅끼리는 대화를 공유하지 않으니 계속 쓸 정보는 지침이나 파일에 둔다.","좋은 지침의 5칸: 역할 · 받는 것 · 순서 · 출력 · 지킬 것.","바이브 코딩: 한 앱 = 한 프로젝트, 기능 하나 = 세션 하나. 기능이 끝날 때마다 컨텍스트의 index.html을 최신으로 교체한다."],"blocks":[{"type":"table","head":["서비스","2026년 지금"],"rows":[["Gemini","Gems가 스킬(Skills)로 바뀌는 중. 입력창에 / 로 불러 쓰기"],["ChatGPT","GPTs는 2026년 12월 11일 종료 예정. 스킬·프로젝트로 옮기기"],["Claude","프로젝트 = 지침 + 지식(파일). 무료 계정도 5개까지"]]},{"type":"table","head":["이럴 때","이렇게"],"rows":[["규칙을 안 지켜요","규칙을 짧게, 번호로, '반드시'를 붙여서"],["규칙끼리 부딪쳐요","'짧게' vs '자세히' 같은 충돌을 하나로"],["지침에 테스트 문장까지 넣었어요","지침엔 규칙만, 할 일은 세션에"],["새 기능이 옛 기능을 지워요","컨텍스트 index.html 최신으로 교체"],["한 세션에서 계속 꼬여요","새 세션에서 기능 하나만 다시"],["사용량이 빨리 닳아요","생각 강도 낮추기, 큰 파일은 필요한 것만"]]}],"prompts":[{"id":"d3s38_0","lab":"프로젝트 지침 (복사해서 컨텍스트에)","where":"+ 컨텍스트 추가 (또는 프로젝트 화면 오른쪽 컨텍스트)","text":"너는 \"APE 프롬프트 생성기\"야.\n## 사용자가 주는 것\n- 작업 / 원하는 결과물 / 피해야 할 것\n- 빠진 정보가 있으면 만들기 전에 최대 3개까지 먼저 질문해\n## 매번 이 순서로\n1. 서로 다른 전략(역할 부여·단계 지시·예시 포함·제약 명시·독자 설정)으로 후보 프롬프트 5개\n2. 명확성·완전성·실행 가능성·품질 유도력 각 25점으로 표 채점\n3. 상위 2개의 장점을 합쳐 최종 프롬프트 1개\n## 출력 형식\n채점 표 → 최종 프롬프트(코드 블록, 바로 복사 가능) → 이유 3줄 → 주의할 점 2줄\n## 지킬 것\n- 한국어, 쉬운 말\n- 사실·숫자를 지어내지 말고 모르면 {빈칸}으로 남기기","kind":"try"},{"id":"d3s39_0","lab":"① 작업만 입력","where":"프로젝트 화면 \"새 세션\" 입력창","text":"작업: 바이어 첫 연락 이메일\n원하는 결과물: 답장을 받고 싶게 만드는 짧은 영문 메일\n피해야 할 것: 과장 광고, 긴 회사 소개","kind":"try"},{"id":"d3s39_1","lab":"② 다른 작업도","where":"프로젝트 화면으로 돌아가 또 새 세션","text":"작업: 인스타그램 제품 소개 글\n원하는 결과물: 20대가 저장하고 싶은 글\n피해야 할 것: 뻔한 표현, 해시태그 10개 이상","kind":"try"},{"id":"d3s40_0","lab":"📧 바이어 메일 비서","where":"새 프로젝트 → + 컨텍스트 추가","text":"너는 10년 차 무역 실무자이자 영문 메일 비서야.\n- 모든 메일은 영어 + 아래에 한국어 뜻\n- 3단락, 150단어 이내, 정중하고 간결하게\n- 단가·납기·조건은 내가 준 정보만 쓰고 없으면 [확인 필요]\n- 끝에 \"보내기 전 확인할 것\" 3개\n테스트: \"샘플 발송 지연 사과 메일, 3일 늦어짐\"","kind":"try"},{"id":"d3s40_1","lab":"🌏 시장조사 리포터","where":"새 프로젝트 → + 컨텍스트 추가","text":"너는 수출 시장조사 리포터야.\n- 국가·품목을 주면 5W1H 표로 정리\n- 숫자에는 출처를 함께, 불확실하면 🟡 표시\n- 마지막에 바이어·소비자·경쟁사 관점 1줄씩\n- 웹 검색이 필요하면 검색하고 링크를 붙여 줘\n테스트: \"인도네시아 · 한국 화장품\"","kind":"try"},{"id":"d3s40_2","lab":"바이브 코딩 코치","where":"새 프로젝트 → + 컨텍스트 추가","text":"너는 비전공자를 돕는 바이브 코딩 코치야.\n- 나는 HTML 파일 하나만 다룰 수 있어\n- 코드 전에 화면 구성을 3줄로 먼저 확인받기\n- 코드는 항상 전체 코드로, 외부 라이브러리 금지\n- 끝에 \"다음에 해 볼 개선 3가지\"\n- 설명은 초등학생도 알게\n테스트: \"D-day 계산기 만들어 줘\"","kind":"vibe"},{"id":"d3s33_0","lab":"실습 · 내 분야 APE 만들기","where":"Claude 새 채팅 → 결과를 뒤의 \"프로젝트 지침\"에 넣기","text":"나는 (무역 / 유튜브 채널 운영 / 쇼핑몰 등) 분야에서 일해. 이 분야에 최적화된 APE 마스터 프롬프트를 만들어줘. Gems에 넣어서 계속 쓰고 싶어. 필요한 정보가 있으면 먼저 하나씩 질문해줘.","kind":"try"}],"extra":{"title":"바이브 코딩용 프로젝트 만들기","prompts":[{"id":"d3s42_0","lab":"① 이름 칸","where":"\"무엇을 작업 중이신가요?\" 칸","text":"무역 퀴즈 앱","kind":"try"},{"id":"d3s42_1","lab":"② 목표 칸","where":"\"어떤 목표를 달성하려고 하시나요?\" 칸","text":"무역학과 1학년이 FOB·CIF 같은 무역 용어를 게임처럼 외우는 웹앱을 만든다.\n나는 코딩 초보라 HTML 한 파일로만 만들고, 기능을 하나씩 추가해 간다.","kind":"try"},{"id":"d3s43_0","lab":"코딩 규칙 (복사)","where":"프로젝트 → 컨텍스트 → 추가","text":"# 코딩 규칙 (모든 세션에서 지킬 것)\n## 나에 대해\n- 코딩을 처음 배우는 비전공자, HTML 파일 하나만 다룰 수 있음\n## 기술\n- HTML·CSS·JavaScript를 index.html 한 파일에\n- 외부 라이브러리·서버·로그인·데이터베이스 금지\n## 작업 방식\n1. 코드를 쓰기 전에 \"이렇게 만들게요\" 계획을 3줄로 먼저 보여 주고 내 OK를 기다리기\n2. 한 번에 기능 하나만\n3. 코드는 항상 index.html 전체 코드로\n4. 기존 기능·디자인은 절대 바꾸지 않기 (요청한 부분만)\n5. 끝에 \"바뀐 점 3줄\" + \"제가 확인할 것 2개\"\n## 디자인\n- 큰 글씨, 큰 버튼, 모바일에서도 잘 보이게, 메인 색 파랑\n## 설명\n- 초등학생도 알게 쉬운 말로, 전문 용어는 괄호로 풀어서","kind":"try"},{"id":"d3s44_0","lab":"기획서 (복사 · 내 앱에 맞게 수정)","where":"프로젝트 → 컨텍스트 → 추가 (제목: 기획서)","text":"# 기획서: 무역 용어 퀴즈 앱\n## 누가, 왜\n무역학과 1학년이 FOB·CIF 같은 용어를 게임처럼 외우기\n## 화면\n[ ] 화면 1 시작: 앱 이름, 난이도 버튼 3개(쉬움·보통·어려움), 시작 버튼\n[ ] 화면 2 퀴즈: 4지선다 10문제, 15초 타이머, 정답 초록·오답 빨강\n[ ] 화면 3 결과: 점수, 틀린 문제와 정답 목록, 다시 하기 버튼\n## 문제 데이터\n- 무역 용어 30개 중 매번 10개 무작위\n## 나중에 (지금은 안 함)\n- 최고 기록 저장, 효과음","kind":"try"},{"id":"d3s44_1","lab":"기획서가 없으면 만들기","where":"프로젝트 \"새 세션\" 입력창","text":"제 앱의 기획서를 만들고 싶어요.\n컨텍스트의 코딩 규칙에 맞게, 한 번에 하나씩 질문해 주세요 (최대 5개).\n다 묻고 나면 위 형식(누가·왜 / 화면 체크리스트 / 데이터 / 나중에)으로 기획서를 정리해 주세요.","kind":"try"},{"id":"d3s45_0","lab":"세션 ① 첫 화면","where":"프로젝트 \"새 세션\" 입력창","text":"기획서의 [화면 1 시작]만 만들어 주세요.\n코딩 규칙대로 계획 3줄을 먼저 보여 주세요.","kind":"try"},{"id":"d3s45_1","lab":"같은 세션 · 계획 OK 후","where":"같은 세션에 이어서","text":"좋아요, 그 계획대로 진행해 주세요.","kind":"try"},{"id":"d3s45_2","lab":"세션 ② 다음 기능","where":"다시 프로젝트 화면 → 새 세션","text":"컨텍스트의 index.html에 기획서의 [화면 2 퀴즈]를 추가해 주세요.\n화면 1은 그대로 두고, 계획 3줄부터 보여 주세요.","kind":"try"},{"id":"d3s45_3","lab":"버그가 났을 때 (새 세션)","where":"프로젝트 \"새 세션\" 입력창","text":"컨텍스트의 index.html에서 (어떤 상황)일 때 (무슨 문제)가 생겨요.\n바로 고치지 말고 원인 후보 3개를 쉬운 말로 먼저 알려 주세요.","kind":"try"},{"id":"d3s46_0","lab":"기획서 체크 업데이트","where":"기능을 만든 그 세션에 이어서","text":"이번 세션에서 완성한 기능을 기획서에 반영해 주세요.\n완료한 항목은 [x]로 바꾸고, 새로 정한 내용이 있으면 추가해서\n기획서 전체를 다시 보여 주세요.","kind":"try"},{"id":"d3s47_0","lab":"지침 점검 받기","where":"프로젝트 \"새 세션\" 입력창","text":"컨텍스트에 있는 코딩 규칙과 기획서를 읽고 점검해 주세요.\n1) 모호하거나 서로 충돌하는 규칙\n2) 빠져서 결과가 들쭉날쭉할 수 있는 규칙\n3) 초보자에게 너무 어려운 요구\n각각 고친 문장을 제안하고, 마지막에 고친 코딩 규칙 전체를 보여 주세요.","kind":"try"}]},"caution":"GPTs 종료일 같은 서비스 정보는 강의 시점 기준이라 바뀔 수 있다."},{"id":"keys","group":"advanced","title":"프롬프트를 잘 쓰는 5가지 열쇠","en":"5 Keys","summary":"지금까지 배운 모든 것을 다섯 개로 줄이면.","points":["① 명확하고 구체적으로: AI는 내 마음을 모른다. 숫자와 조건으로.","② 충분한 맥락: 목적지까지 가는 상세 내비게이션을 찍어 주기.","③ 말보다 샘플 하나: 백 마디 설명보다 예시 하나.","④ 큰 일은 잘게 쪼개기: 기획 → 카테고리 → 상세 순서대로.","⑤ AI를 파트너로: 결과는 완성본이 아니라 초안. 대화로 다듬는다.","명령 한 번 = 크레딧 한 번(Lovable·Cursor 등). 최적으로 만들되, 너무 길면 잊으니 잘게 쪼개서 보낸다."],"blocks":[{"type":"table","head":["열쇠","아쉬운 예","좋은 예"],"rows":[["① 구체적으로","\"마케팅 좀 알려줘\"","\"월 예산 50만 원으로 40대 타겟 매출을 20% 올릴 아이디어 3개 제안해줘\""],["② 맥락 주기","\"은퇴 준비 글 써줘\"","\"나는 10년 차 재무 상담사야. 불안해하는 50대 직장인에게 따뜻한 조언으로 써줘\""],["③ 샘플 주기","\"감동적인 이메일 써줘\"","\"내가 쓴 이 예시와 비슷한 톤앤매너로 고객 감사 메일 써줘\""]]}],"prompts":[{"id":"d3s53_0","lab":"실습 · 열쇠 ①","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"월 예산 50만 원으로 40대 타겟 매출을 20% 올릴 마케팅 아이디어 3개 제안해줘","kind":"try"},{"id":"d3s53_1","lab":"실습 · 열쇠 ③","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"내가 쓴 아래 예시와 비슷한 톤앤매너로 고객 감사 메일 써줘\n'''\n고객님, 늘 믿고 찾아 주셔서 감사합니다. 작은 정성이지만 다음 주문에 쓰실 수 있는 쿠폰을 함께 보내드려요.\n'''","kind":"try"},{"id":"d3s54_0","lab":"실습 · 열쇠 ④ 쪼개기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"먼저 사업계획서의 핵심 컨셉 3개만 제안해줘. 그중 하나로 상세 목차를 짜보자.","kind":"try"},{"id":"d3s54_1","lab":"실습 · 열쇠 ⑤ 다듬기","where":"Gemini 새 채팅에 붙여넣기 → Enter","text":"이 부분은 좀 더 전문가답게 고쳐줘. 실제 사례를 하나 더 추가해줘.","kind":"try"},{"id":"d3s55_0","lab":"바이브 코딩에서","where":"Claude 새 채팅","text":"아래는 제가 쓰려던 바이브 코딩 요청이에요.\n\"쇼핑몰 만들어줘\"\n이 요청을 5가지 열쇠(구체적으로·맥락·샘플·쪼개기·다듬기)로\n각 20점 만점 채점해 주세요.\n그리고 쪼개기를 적용해서 \"한 번에 하나씩 보낼 요청문 3개\"로\n나눠서 다시 써 주세요. (1번 요청문은 화면 하나만)","kind":"vibe"},{"id":"d3s56_0","lab":"AI 심사위원","where":"Gemini 새 채팅","text":"당신은 깐깐한 프롬프트 심사위원입니다.\n아래 두 프롬프트를 5가지 열쇠\n(구체적으로 · 맥락 · 샘플 · 쪼개기 · 다듬기 가능성)로\n각 20점 만점 채점하고 표로 비교해 주세요.\n마지막에 \"고친 후\" 프롬프트를 더 좋게 만들 한 가지 팁을 주세요.\n#고치기 전\n(나쁜 프롬프트)\n#고친 후\n(내가 고친 프롬프트)","kind":"try"}],"work":["보고서·메일 요청 전에 열쇠 5개 체크 → 다시 시키는 횟수 감소","긴 작업은 조사 → 정리 → 문서화로 쪼개기","결과를 받은 뒤 '더 짧게', '숫자 위주로' 다듬기"]},{"id":"generator","group":"tools","title":"APE 프롬프트 생성기","en":"Prompt Generator","summary":"작업 · 원하는 결과물 · 피해야 할 것 세 줄만 쓰면 APE 프롬프트를 조립해 준다.","tool":"generator"},{"id":"summary","group":"tools","title":"한 장 정리","en":"Summary Map","summary":"기법 → 무역 업무 → 바이브 코딩, 한 표로 보기.","blocks":[{"type":"table","head":["기법","무역 업무에서","바이브 코딩에서"],"rows":[["세 가지 유형","반복 업무는 지침형·함수형 틀로","함수형으로 프로그램 주문"],["예시 주기","메일 제목·HS 형식 통일","연습용 데이터 형식 맞추기"],["페르소나","실무자·전문가 시각으로 검토","\"친절한 시니어 개발자\" → 코드 + 설명"],["마크다운","지시서·보고서 요청 틀","요구사항 문서 (설계도)"],["강도 · 톤","보안 규칙, 길이, 바이어별 말투","\"기존 기능은 절대 그대로\" + 숫자로 수정"],["대안 · 이용자","비교표로 받고 내가 결정","만들기 전에 방법 3가지 비교"],["레시피 · 역질문 · 검증","절차 체크리스트, 빠진 정보 묻기","기획은 역질문, 에러는 쪼개서 확인"],["게임 플레이","협상 롤플레이, 신입 교육 퀴즈","게임 규칙 = 앱 설계서"],["질문 개선","막연한 지시를 조사 질문으로","\"만들어 줘\" 전에 요청문 다듬기"],["팩트 체크","관세율·규정 확인 목록","코드 뒤 \"직접 확인할 것\" 신호등"],["메타 언어","/메일 · /요약 팀 단축어","/수정 · /설명 · /점검"],["리플렉션","초안 → 비평 → 개선본","AI가 자기 코드 셀프 리뷰"],["아웃라인 확장","목차 먼저, 섹션별 확장","화면 목록 먼저, 하나씩 만들기"],["컨텍스트 · 무한 생성","회사 상황 고정, 메일 대량 생성","프로젝트 설명서(CLAUDE.md), 더미 데이터"],["프레임워크","CO-STAR 제안서, ROSES 협상","RISEN으로 코드 요청"],["다중 관점","계약·신제품을 이해관계자별로 검토","사용자·디자이너·개발자·보안 4인 리뷰"],["심사숙고","진출국·가격 결정, 반론 먼저","만들기 전에 방법 비교 → 방향 결정"],["APE","반복 업무용 최적 프롬프트, 팀 매뉴얼","최적 코딩 요청문을 AI가 먼저 작성"],["Claude 프로젝트","메일 비서 · 시장조사 리포터","바이브 코딩 코치, 코딩 규칙 파일"],["5가지 열쇠","요청 전 체크, 쪼개서 진행","크레딧 아끼기, 화면 하나씩 요청"]]}]},{"id":"mission","group":"tools","title":"과제 · 미션 프롬프트","en":"Assignments","summary":"이 사이트를 만들고 고치고 배포할 때 쓴 요청문 모음.","points":["DAY 1: 정리 내용을 왼쪽 메뉴가 있는 HTML로 → DAY 2: 새 섹션 추가 → DAY 3: 반응형으로 고쳐 배포, 프롬프트 생성기 추가."],"prompts":[{"id":"d1s72_0","lab":"HTML 만들기 프롬프트 예시","where":"Claude 새 채팅 → 코드를 VS Code에 저장 (다음 장 순서)","text":"#역할\n당신은 웹 퍼블리셔입니다\n#작업\n아래 정리한 프롬프트 기법 내용을 학습용 웹페이지로 만들어주세요\n'''\n(여기에 내 정리 내용 붙여넣기)\n'''\n#조건\n- HTML, CSS만 사용\n- 왼쪽에 기법별 목차 메뉴\n- 예시 프롬프트는 회색 상자에 넣고 복사 버튼 추가\n#출력\nindex.html 파일 하나로","kind":"try"},{"id":"d2s77_0","lab":"업데이트 요청 프롬프트","where":"Claude 새 채팅 → 결과를 VS Code index.html에 교체","text":"아래 기존 웹페이지에 새 섹션을 추가해 주세요\n#반드시\n- 기존 메뉴·내용·디자인은 절대 바꾸지 마세요\n#추가할 것\n- 왼쪽 메뉴에 \"DAY 2 패턴\" 과 \"프레임워크\" 추가\n- 각 패턴: 설명 2줄 + 예시 프롬프트(복사 버튼)\n#기존 코드\n'''\n(index.html 전체를 여기에 붙여넣기)\n'''\n#오늘 정리 내용\n'''\n(메모장 정리 내용 붙여넣기)\n'''\n#출력\n수정된 index.html 전체 코드","kind":"try"},{"id":"d3s60_0","lab":"반응형 수정 프롬프트 예시","where":"Claude 새 채팅 → 결과를 VS Code index.html에 교체","text":"#작업\n아래 index.html을 반응형으로 수정해줘\n#조건\n- 휴대폰(가로 768px 이하)에서는 왼쪽 메뉴를 위쪽 햄버거 메뉴(☰)로 바꾸기\n- 예시 프롬프트 상자는 화면 너비에 맞게 줄바꿈\n- 글자 크기는 휴대폰에서도 읽기 편하게\n- 기존 내용과 디자인은 그대로 유지\n#출력\n수정된 index.html 전체 코드\n'''\n(여기에 내 index.html 붙여넣기)\n'''","kind":"try"},{"id":"d3s63_0","lab":"조립기 만들기 (API 키 필요 없음)","where":"Claude 새 채팅 → 미리보기로 바로 사용","text":"#작업\n\"APE 프롬프트 조립기\" 웹페이지를 만들어 주세요\n#기능\n- 입력칸 3개: 작업, 원하는 결과물, 피해야 할 것\n- [조립] 버튼 → 아래 틀에 입력값을 넣은 완성 프롬프트를 보여 주기\n- [복사] 버튼, [Claude 열기] [Gemini 열기] 링크 버튼\n- [예시 채우기] 버튼 (클레임 답장 예시)\n#틀\n작업: {작업} / 원하는 결과물: {결과물} / 피해야 할 것: {피할 것}\n이 작업을 위한 프롬프트 후보 5개를 서로 다른 전략으로 만들고 채점한 뒤 최종 프롬프트 1개를 주세요.\n#조건\n- HTML 한 파일, API 사용 안 함, 반응형, 큰 글씨","kind":"try"},{"id":"d3s62_0","lab":"생성기 만들기 프롬프트 예시","where":"Claude 새 채팅 → VS Code에 generator.html로 저장","text":"#역할\n당신은 웹 개발자입니다\n#작업\nOpenAI API를 사용하는 '프롬프트 생성기' 웹페이지를 만들어주세요\n#기능\n- 입력칸 3개 : 작업, 원하는 결과물, 피해야 할 것\n- [생성] 버튼을 누르면 APE 방식으로 최적 프롬프트 1개와 이유를 보여주기\n- 결과 옆에 복사 버튼\n- 사용자가 자신의 API 키를 화면에서 입력 (코드에 키를 넣지 않기)\n#조건\n- HTML, CSS, JavaScript 파일 하나로\n- 반응형\n- 초보자도 이해할 수 있게 주석 달기","kind":"try"}],"caution":"API 키는 비밀번호와 같다. 공개 사이트 코드에 넣지 말고, 사용자가 화면에서 직접 입력하게 한다."}],"gen":{"quick":"작업: (           )\n원하는 결과물: (           )\n피해야 할 것: (           )\n이 작업을 위한 프롬프트 후보 5개를 서로 다른 전략으로 만들고\n명확성·완전성·실행 가능성·품질 유도력 각 25점으로 채점한 뒤\n가장 좋은 최종 프롬프트 1개만 코드 블록으로 보여 주세요.\n그리고 그 최종 프롬프트를 바로 실행한 결과물도 보여 주세요.","master":"#역할\n당신은 프롬프트 엔지니어링 전문가입니다\n주어진 작업에 대해 최적의 프롬프트를 자동으로 생성, 평가, 개선합니다\n##APE 실행 순서\n### step 1 : 후보 프롬프트 생성\n아래 작업을 위한 프롬프트 후보 10개를 생성합니다\n각 후보는 서로 다른 전략을 사용해야 합니다\n전략 유형\n- 역할 부여형 : \"당신은 xxx 전문가입니다\"\n- 단계별 지시형 : \"step 1 : ... step 2 : ...\"\n- 예시 포함형 : \"다음과 같이 ~해주세요 [예시]\"\n- 제약 명시형 : \"반드시 ~하되, ~하지 마세요\"\n- 목적 중심형 : \"최종 목표는 ~이며 ...\"\n- 독자 설정형 : \"~을 모르는 사람도 이해하도록\"\n- 형식 지정형 : \"결과를 [형식]으로 출력하세요\"\n- 품질 기준형 : \"~한 기준으로 평가했을 때 90점 이상...\"\n- 역방향형 : \"나쁜 예시는 ~이고, 좋은 예시는 ~\"\n- 메타 지시형 : \"이 작업의 본질은 ~이며 ...\"\n### step 2 : 각 후보 자체 평가\n각 프롬프트에 대해 아래 기준으로 점수 매기기 :\n명확성(0~25점) : 지시가 모호하지 않은가\n완전성(0~25점) : 필요한 정보가 다 있는가\n실행 가능성(0~25점) : AI가 바로 실행하는가\n품질 유도력(0~25점) : 높은 품질의 결과를 이끌어 내는가\n총 100점 만점\n### step 3 : 상위 3개 선택 후 교차 최적화\n상위 3개 프롬프트의 강점을 결합하여 최종 최적 프롬프트 1개 생성\n### step 4 : 최적 프롬프트 출력\n- 최적 프롬프트 전문\n- 왜 이것이 최선인지 설명\n- 사용 시 주의 사항","masterInput":"### 작업 입력\n작업 : {고객 클레임 이메일 답장 작성}\n원하는 결과물 : {고객이 화가 풀리고 우리 회사를 신뢰하게 하는 답장}\n피해야 할 것 : {방어적 태도, 책임 회피, 형식적인 사과}"},"counts":{"topics":34,"prompts":174}};
